        ObjVoxGpu g{}; float* rows[3] = { g.r0, g.r1, g.r2 };
        for (int i = 0; i < 3; i++) { rows[i][0] = (float)(r[i].x / size[i]); rows[i][1] = (float)(r[i].y / size[i]); rows[i][2] = (float)(r[i].z / size[i]); rows[i][3] = (float)((dot(r[i], d) + piv[i]) / size[i]); }
