    // ---- Body and movement: the player's size, moves, health (game.txt)
    void BodyTab() {
        PlayerRules& r = game.player; bool ch = false;
        auto sl = [&](const char* l, float* v, float a, float b, const char* f) { Prop(l); ImGui::PushID(l); ch |= ImGui::SliderFloat("##v", v, a, b, f); ImGui::PopID(); };
        ImGui::SeparatorText("Body");
        float hb = r.height; sl("Height", &r.height, 0.3f, 6, "%.2f blocks");
        if (r.height != hb && hb > 0) r.eyeHeight = std::min(r.height - 0.05f, r.eyeHeight * r.height / hb);   // the eyes stay at the same place on the body
        sl("Width", &r.width, 0.2f, 4, "%.2f blocks");
        sl("Eye height", &r.eyeHeight, 0.1f, std::max(0.15f, r.height - 0.02f), "%.2f blocks");
        sl("Steps up by itself", &r.stepHeight, 0, 2, "%.2f blocks");
        Hint("Fits through gaps at least %.2f wide and %.2f tall.", r.width, r.height);
        ImGui::SeparatorText("Moving");
        sl("Walk speed", &r.walkSpeed, 1, 15, "%.1f blocks/s");
        Prop("Can sprint (Ctrl)"); ch |= ImGui::Checkbox("##sprint", &r.canSprint);
        if (r.canSprint) sl("Sprint speed", &r.sprintSpeed, 1, 25, "%.1f blocks/s");
        sl("Jump height", &r.jumpHeight, 0.3f, 8, "%.2f blocks");
        sl("Gravity", &r.gravity, 4, 80, "%.0f");
        Hint("Items change some of this while playing (Hi-Jump Boots, Space Jump, Speed Booster, the Gravity Suit...): Items tab.");
        ImGui::SeparatorText("Morph Ball (C)");
        sl("Size", &r.ballSize, 0.2f, 3, "%.2f blocks");
        sl("Rolling speed", &r.ballSpeed, 1, 20, "%.1f blocks/s");
        sl("Morph effect", &r.morphFx, 0, 2, r.morphFx <= 0 ? "none" : "%.2f");
        if (r.morphFx > 0) {
            float c[3] = { ((r.morphColor >> 16) & 255) / 255.f, ((r.morphColor >> 8) & 255) / 255.f, (r.morphColor & 255) / 255.f }; Prop("... colour");
            if (ImGui::ColorEdit3("##mfc", c, ImGuiColorEditFlags_NoInputs)) { r.morphColor = ((uint32_t)std::lround(c[0] * 255) << 16) | ((uint32_t)std::lround(c[1] * 255) << 8) | (uint32_t)std::lround(c[2] * 255); ch = true; }
            Prop("... the HUD too"); ch |= ImGui::Checkbox("##mfh", &r.morphHudFx);
            Hint("Morphing: an energy shell collapses onto the ball (or bursts from it), sparks, a flash of light; the HUD flares up and its energy sparks away. Standing up next to a wall or a step: you are pushed to where you fit.");
        }
        Prop("Model");
        if (ImGui::BeginCombo("##bm", r.ballModel.c_str())) {
            if (ImGui::Selectable("@morph-ball (built in)", r.ballModel == "@morph-ball")) { r.ballModel = "@morph-ball"; ch = true; }
            for (const std::string& n : PartModels()) if (ImGui::Selectable(n.c_str(), r.ballModel == n)) { r.ballModel = n; ch = true; }
            ImGui::EndCombo();
        }
        ModelMaterialUI(r.ballModel.empty() ? std::string("@morph-ball") : r.ballModel);
        if (ImGui::TreeNode("How it rolls (3D editor)")) { ch |= BallEditorUI(r); ImGui::TreePop(); }
        Hint("Whether you have it (and the Bombs, Spring Ball, Power Bombs...): Items tab.");
        ImGui::SeparatorText("Health and dying");
        sl("Health", &r.maxHealth, 1, 500, "%.0f");
        sl("Lava damage", &r.lavaDamage, 0, 200, "%.0f per second");
        sl("Fall damage", &r.fallDamage, 0, 50, r.fallDamage <= 0 ? "off" : "%.0f per block (after 4)");
        sl("Death below height", &r.voidDepth, -512, 0, "y = %.0f");
        sl("Respawn after", &r.respawnDelay, 0, 10, "%.1f s");
        sl("Bounced shots hurt you", &r.bounceDamage, 0, 2, r.bounceDamage <= 0 ? "never" : "%.2f x their damage");
        Prop("Quick save from the pause menu"); ch |= ImGui::Checkbox("##qsave", &r.quickSave);
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("On: the pause menu's Quick save saves anywhere.\nOff: only Save Stations save (like Prime); the button is greyed out.");
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("A door that needs another weapon sends the shot back; if it hits you, this much of its damage.\nOnce a door is opened with the right weapon, any shot opens it from then on (saved).");
        ImGui::SeparatorText("The death sequence");
        Prop("Death sequence"); ch |= ImGui::Checkbox("##dfx", &r.deathFx);
        if (r.deathFx) {
            sl("The hit", &r.deathHit, 0, 2, r.deathHit <= 0 ? "left out" : "%.2f s");
            Prop("... in slow motion"); ch |= ImGui::Checkbox("##dsm", &r.deathSlowMo);
            sl("Static", &r.deathStatic, 0, 4, r.deathStatic <= 0 ? "left out" : "%.2f s");
            sl("... how strong", &r.deathStaticAmount, 0, 2, "%.2f");
            { float c[3] = { ((r.deathStaticColor >> 16) & 255) / 255.f, ((r.deathStaticColor >> 8) & 255) / 255.f, (r.deathStaticColor & 255) / 255.f }; Prop("... its colour");
              if (ImGui::ColorEdit3("##dsc", c, ImGuiColorEditFlags_NoInputs)) { r.deathStaticColor = ((uint32_t)std::lround(c[0] * 255) << 16) | ((uint32_t)std::lround(c[1] * 255) << 8) | (uint32_t)std::lround(c[2] * 255); ch = true; } }
            sl("The suit shuts down", &r.deathShutdown, 0, 4, r.deathShutdown <= 0 ? "left out" : "%.2f s");
            Prop("... the view sinks"); ch |= ImGui::Checkbox("##ddr", &r.deathDrop);
            sl("Switching off", &r.deathOff, 0, 2, r.deathOff <= 0 ? "left out" : "%.2f s");
            Prop("... like an old TV"); ch |= ImGui::Checkbox("##dtv", &r.deathTvOff);
            Prop("Any button skips"); ch |= ImGui::Checkbox("##dsk", &r.deathSkip);
            Hint("%.1f s in all. The hit: slow motion, a flash. Static: the visor fills with noise, the HUD flickers and drops out piece by piece. The suit shuts down: colour drains away, it goes dark, the view sinks. Then it switches off - and the Death screen (Screens) comes, or you come back. Sounds: Player > Sounds > Death.", r.deathLength());
        }
        Hint("Energy Tanks add to the health, suits take damage away: Items tab.");
        ImGui::Spacing();
        if (ImGui::Button("Reset all of this")) { r = PlayerRules{}; ch = true; }
        if (ch) game.save(gamePath);
        Hint("Saved by itself. Press F5 to try it.");
    }
    // ---- Items: everything Samus can find (items.txt); beams and missiles come from the Weapons tab
    ItemSet items = defaultItems(); ItemEffects itemFx; PlayerRules playRules;
    void SaveItems() { if (!projectDir.empty()) saveItems(projectDir + "/items.txt", items); }
    int ItemHave(const std::string& n) const { auto it = inv.counts.find(n); return (it == inv.counts.end() ? 0 : it->second) + (inv.keys.count(n) ? 1 : 0); }
    void UpdateItemRules() {   // what the items you have do: the rules the player plays by right now
        playRules = game.player;
        if (!playMode) { itemFx = ItemEffects{}; itemFx.maxHealth = game.player.maxHealth; return; }
        itemFx = itemEffects(items, game.player, [this](const std::string& n) { return ItemHave(n); });
        playRules.maxHealth = itemFx.maxHealth; playRules.jumpHeight = itemFx.jumpHeight; playRules.lavaDamage = game.player.lavaDamage * itemFx.lavaTaken;
        playRules.damageTaken = itemFx.damageTaken; playRules.freeInLiquid = itemFx.freeInLiquid; playRules.airJumps = itemFx.airJumps;
        playRules.speedBooster = itemFx.speedBooster; playRules.boostAfter = itemFx.boostAfter; playRules.boostSpeed = itemFx.boostSpeed;
        playRules.springBall = itemFx.springBall; playRules.springJump = itemFx.springJump;
    }
    int MissileMax() const { return weapons.missileMax + itemFx.missileBonus; }
    int PowerBombMax() const { return items.powerBombMax + itemFx.powerBombBonus; }
    // ================================================================== the item pop-up ("Item get" screen; banners for small things)
    struct ItemGetNow { std::string name, title, text, model; } itemGetNow;
    struct ItemBanner { std::string title, text; double t = -1; } itemBanner;
    HudTarget itemModelView; ComPtr<ID3D11DepthStencilView> itemModelDSV; int imDW = 0, imDH = 0, imWantW = 0, imWantH = 0; std::string imModel;
    float musicDuckNow = 1; bool itemGetKeyPrev = true;
    static constexpr int TAG_FANFARE = 38; std::set<uint32_t> poppedIds;   // the fanfare (one at a time; stops when the pop-up closes); pickups that already popped up this play
    int PopupHintOf(const std::string& n, int pickupType = -1) const {
        for (const Beam& b : weapons.beams) if (b.name == n) return HINT_BEAM;
        for (const MissileType& m : weapons.missileTypes) if (m.name == n) return HINT_MISSILE;
        if (n == "Morph Ball") return HINT_MORPH;
        if (n == "Bombs") return HINT_BOMBS;
        if (pickupType == (int)PickupType::Key || pickupType == (int)PickupType::Collectible) return HINT_KEY;
        return HINT_NONE;
    }
    std::string ItemFill(const std::string& s) { return menuFill(s, [&](const std::string& n) { return MenuValue(n); }); }
    void ItemGetShow(const WorldObject& o) {   // a pickup was taken: its pop-up, banner or just the sound
        const std::string& n = o.pickup.name;
        if (!poppedIds.insert(o.id).second) return;   // (never twice for the same pickup)
        if (CurScreen() && CurScreen()->role == ScreenRole::ItemGet) return;   // (one is showing already)
        GetPopup p = popupFor(items, n, PopupHintOf(n, (int)o.pickup.type));
        std::string key = "got:" + n; bool first = !evRun.flags.count(key); evRun.flags.insert(key);   // (saved with the game: the first one stays the first)
        bool counted = popupCounted(items, n) || o.pickup.type == PickupType::Collectible;
        int style = popupStyleNow(p, counted, first ? 1 : 2);
        itemGetNow = { n, p.title, p.text, p.model.empty() ? o.model : p.model };
        int scr = screens.byRole(ScreenRole::ItemGet);
        if (style == POPUP_BIG && scr >= 0) {
            const SoundUse& fan = !p.fanfare.empty() ? p.fanfare : items.fanfare;
            StopSounds(TAG_FANFARE);
            if (!fan.empty()) PlaySoundIn(SND_MUSIC, fan, 1.f, nullptr, TAG_FANFARE, false); else GameSnd(&PlayerSounds::itemGet, SND_WORLD);
            itemGetKeyPrev = true; ShowScreen(scr, false);
            return;
        }
        GameSnd(&PlayerSounds::itemGet, SND_WORLD);
        if (style == POPUP_NONE) return;
        itemBanner.title = ItemFill(p.title); itemBanner.text = ItemFill(p.text); itemBanner.t = 0;   // a banner: the game goes on
    }
    void ItemGetInput() {   // the pop-up: after its hold time, jump / fire / Enter / a click closes it
        mc::Screen* sc = CurScreen();
        bool any = GetForegroundWindow() == hwnd && (ActDown(Act::Jump) || ActDown(Act::Fire) || Down(VK_RETURN) || Down(VK_SPACE) || Down(VK_LBUTTON));
        bool press = any && !itemGetKeyPrev; itemGetKeyPrev = any;
        if (!sc || screenT < sc->holdMin || !press) return;
        PlayUi(1); StopSounds(TAG_FANFARE); CloseScreens(); if (playMode) { paused = false; Capture(true); }
    }
