    // ---- the timeline: one row per item (back to front), its bar from when it appears to when it goes, fades as slopes,
    // keyframes as diamonds; the playhead (what the canvas shows), the screen's end. Drag bars, their ends, keys, the playhead.
    static ImU32 TlKindColor(ScreenItemKind k, int a) {
        uint32_t c = k == ScreenItemKind::Text ? 0x4C8DFF : k == ScreenItemKind::Image ? 0x45B884 : k == ScreenItemKind::Sound ? 0xA875F0 : k == ScreenItemKind::Button ? 0xD99A3A : k == ScreenItemKind::Panel ? 0x7D8C9C : 0x6A7A8A;
        return IM_COL32((c >> 16) & 255, (c >> 8) & 255, c & 255, a);
    }
    void ScreenTimeline(mc::Screen& sc, bool& ch, float height) {
        float ui = settings.uiScale; ImGuiIO& io = ImGui::GetIO(); float len = screenLength(sc);
        // ---- the bar above: play, back to the start, the time, adding things at the playhead, snapping, zoom
        if (ImGui::Button(scrPlaying ? "Pause" : "Play", ImVec2(64 * ui, 0))) {
            scrPlaying = !scrPlaying; scrAudible = scrPlaying;
            if (scrPlaying) { if (scrPlayT >= len) scrPlayT = 0; scrPrevT = scrPlayT - 0.001; scrTyped.clear(); }
        }
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("Play from the playhead, with its sounds (typing, sound cues).");
        ImGui::SameLine(); if (ImGui::Button("|<")) { scrPlayT = 0; scrPrevT = -1; scrTyped.clear(); }
        ImGui::SameLine(); ImGui::AlignTextToFramePadding(); ImGui::Text("%5.2f s", scrPlayT); ImGui::SameLine(); ImGui::TextDisabled(sc.duration > 0 ? "of %.1f s" : "(stays: no end)", sc.duration);
        auto addHere = [&](ScreenItemKind k) {
            ScreenItem it; it.kind = k; float t = (float)scrPlayT; it.showAt = t; it.fade = 0.5f;
            int n = 1; for (const ScreenItem& e : sc.items) if (e.kind == k) n++;
            if (k == ScreenItemKind::Text) { it.name = "Text " + std::to_string(n); it.text = "New text"; it.x = 0.15f; it.y = 0.38f; it.w = 0.7f; it.h = 0.2f; it.textSize = 0.04f; it.hideAt = t + 4; }
            if (k == ScreenItemKind::Image) { it.name = "Picture " + std::to_string(n); it.x = 0.3f; it.y = 0.25f; it.w = 0.4f; it.h = 0.45f; it.hideAt = t + 4; }
            if (k == ScreenItemKind::Sound) { it.name = "Sound " + std::to_string(n); it.fade = 0; }
            sc.items.push_back(it); scrItem = (int)sc.items.size() - 1; tlKeySel = -1; ch = true;
        };
        ImGui::SameLine(); if (ImGui::Button("+ Text")) addHere(ScreenItemKind::Text);
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("A text from the playhead on (4 s; drag its ends to change).");
        ImGui::SameLine(); if (ImGui::Button("+ Picture")) addHere(ScreenItemKind::Image);
        ImGui::SameLine(); if (ImGui::Button("+ Sound")) addHere(ScreenItemKind::Sound);
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("A sound that plays at the playhead (a boom, a voice, a sting).");
        ImGui::SameLine(); ImGui::Checkbox("Snap", &tlSnap);
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("Bars, ends and keys snap to the playhead, to other bars' ends and to 0.05 s.\nHold Shift while dragging: no snapping.");
        ImGui::SameLine(); ImGui::SetNextItemWidth(std::max(60.f, ImGui::GetContentRegionAvail().x)); { float z = tlPps; if (ImGui::SliderFloat("##tlz", &z, 10, 400, "zoom %.0f", ImGuiSliderFlags_Logarithmic)) tlPps = z; }

        // ---- the timeline itself
        float h = std::max(80.f, height - ImGui::GetFrameHeightWithSpacing() - 2);
        ImGui::BeginChild("timeline", ImVec2(0, h), ImGuiChildFlags_Borders, ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse);
        ImVec2 o = ImGui::GetCursorScreenPos(), sz = ImGui::GetContentRegionAvail();
        float nameW = 150 * ui, rulerH = 22 * ui, rowH = 24 * ui, x0 = o.x + nameW, x1 = o.x + sz.x;
        ImGui::InvisibleButton("##tl", ImVec2(std::max(1.f, sz.x), std::max(1.f, sz.y)), ImGuiButtonFlags_MouseButtonLeft | ImGuiButtonFlags_MouseButtonRight);
        bool hov = ImGui::IsItemHovered(); ImDrawList* dl = ImGui::GetWindowDrawList(); ImVec2 mp = io.MousePos;
        int n = (int)sc.items.size(); float rowsH = sz.y - rulerH;
        tlRowScroll = std::clamp(tlRowScroll, 0.f, std::max(0.f, n * rowH - rowsH));
        auto X = [&](float t) { return x0 + (t - tlScroll) * tlPps; };
        auto T = [&](float x) { return tlScroll + (x - x0) / tlPps; };
        auto rowY = [&](int i) { return o.y + rulerH + i * rowH - tlRowScroll; };
        // the wheel: Ctrl zooms (around the mouse), Shift (or a sideways wheel) moves along, else up / down through the rows
        if (hov && (io.MouseWheel != 0 || io.MouseWheelH != 0)) {
            if (io.KeyCtrl) { float tm = T(mp.x); tlPps = std::clamp(tlPps * std::pow(1.2f, io.MouseWheel), 10.f, 400.f); tlScroll = tm - (mp.x - x0) / tlPps; }
            else if (io.KeyShift || io.MouseWheelH != 0 || n * rowH <= rowsH) tlScroll -= (io.MouseWheel + io.MouseWheelH) * 60 / tlPps;
            else tlRowScroll -= io.MouseWheel * rowH * 2;
        }
        if (scrPlaying && stDrag == 0) {   // keeps the playhead in view
            if (X((float)scrPlayT) > x1 - 30) tlScroll = (float)scrPlayT - (x1 - x0) * 0.15f / tlPps;
            if (X((float)scrPlayT) < x0) tlScroll = std::max(0.f, (float)scrPlayT - 0.5f);
        }
        tlScroll = std::max(0.f, tlScroll);
        // snapping: to 0.05 s, and (Snap on) to the playhead, the start, the screen's end and the other bars' ends near the mouse
        auto snap = [&](float v, int self) {
            if (io.KeyShift) return std::max(0.f, v);
            float best = std::round(v / 0.05f) * 0.05f;
            if (tlSnap) {
                float bestPx = 7; auto tryC = [&](float c) { float d = std::fabs(X(c) - X(v)); if (d < bestPx) { bestPx = d; best = c; } };
                tryC((float)scrPlayT); tryC(0); if (sc.duration > 0) tryC(sc.duration);
                for (int i = 0; i < n; i++) if (i != self) { tryC(sc.items[i].showAt); if (sc.items[i].hideAt > 0) tryC(sc.items[i].hideAt); }
            }
            return std::max(0.f, best);
        };

        // ---- drawing
        dl->PushClipRect(o, ImVec2(x1, o.y + sz.y), true);
        dl->AddRectFilled(ImVec2(x0, o.y), ImVec2(x1, o.y + sz.y), IM_COL32(22, 25, 30, 255));
        dl->AddRectFilled(ImVec2(x0, o.y), ImVec2(x1, o.y + rulerH), IM_COL32(34, 38, 46, 255));
        if (sc.duration > 0 && X(sc.duration) < x1) dl->AddRectFilled(ImVec2(std::max(x0, X(sc.duration)), o.y + rulerH), ImVec2(x1, o.y + sz.y), IM_COL32(0, 0, 0, 90));   // past the end
        {   // the ruler: seconds
            float major = tlPps >= 90 ? 1 : tlPps >= 35 ? 2 : tlPps >= 15 ? 5 : 10, minor = tlPps >= 160 ? 0.1f : tlPps >= 60 ? 0.25f : major / 2;
            for (float t = std::floor(T(x0) / minor) * minor; X(t) < x1; t += minor) {
                if (t < -1e-4f) continue; float x = X(t); bool big = std::fabs(std::remainder(t, major)) < 1e-3f;
                dl->AddLine(ImVec2(x, o.y + rulerH * (big ? 0.35f : 0.7f)), ImVec2(x, o.y + rulerH), IM_COL32(150, 160, 175, big ? 200 : 90));
                if (big) { char b[16]; snprintf(b, sizeof b, "%gs", std::round(t * 100) / 100); dl->AddText(ImVec2(x + 3, o.y + 1), IM_COL32(170, 180, 195, 220), b); dl->AddLine(ImVec2(x, o.y + rulerH), ImVec2(x, o.y + sz.y), IM_COL32(255, 255, 255, 12)); }
            }
        }
        for (int i = 0; i < n; i++) {   // the rows
            float y = rowY(i); if (y + rowH < o.y + rulerH || y > o.y + sz.y) continue;
            const ScreenItem& it = sc.items[i]; bool sel = i == scrItem;
            dl->PushClipRect(ImVec2(o.x, o.y + rulerH), ImVec2(x1, o.y + sz.y), true);
            if (sel) dl->AddRectFilled(ImVec2(o.x, y), ImVec2(x1, y + rowH), IM_COL32(255, 200, 60, 22));
            if (i % 2) dl->AddRectFilled(ImVec2(x0, y), ImVec2(x1, y + rowH), IM_COL32(255, 255, 255, 6));
            dl->AddRectFilled(ImVec2(o.x + 4, y + rowH * 0.3f), ImVec2(o.x + 8, y + rowH * 0.7f), TlKindColor(it.kind, 255), 1.f);
            dl->PushClipRect(ImVec2(o.x, y), ImVec2(x0 - 4, y + rowH), true);
            dl->AddText(ImVec2(o.x + 13, y + (rowH - ImGui::GetTextLineHeight()) * 0.5f), sel ? IM_COL32(255, 220, 120, 255) : IM_COL32(210, 215, 225, 255), it.name.c_str());
            dl->PopClipRect();
            dl->PushClipRect(ImVec2(x0, y), ImVec2(x1, y + rowH), true);
            float a = X(it.showAt), b = X(itemEnd(it, len)), top = y + 3, bot = y + rowH - 3;
            bool stays = it.hideAt <= 0 && it.kind != ScreenItemKind::Sound;
            dl->AddRectFilled(ImVec2(a, top), ImVec2(b, bot), TlKindColor(it.kind, sel ? 230 : 160), 3.f);
            if (stays) dl->AddRectFilledMultiColor(ImVec2(std::max(a, b - 40), top), ImVec2(b, bot), IM_COL32(0, 0, 0, 0), IM_COL32(22, 25, 30, 220), IM_COL32(22, 25, 30, 220), IM_COL32(0, 0, 0, 0));   // (goes on)
            if (it.kind != ScreenItemKind::Sound) {   // fading: slopes at both ends
                float fi = std::min(b - a, it.fade * tlPps); if (fi > 1 && it.showAt > 0) dl->AddTriangleFilled(ImVec2(a, top), ImVec2(a + fi, top), ImVec2(a, bot), IM_COL32(0, 0, 0, 110));
                float fo = std::min(b - a, it.fadeOutTime() * tlPps); if (fo > 1 && !stays) dl->AddTriangleFilled(ImVec2(b - fo, top), ImVec2(b, top), ImVec2(b, bot), IM_COL32(0, 0, 0, 110));
            }
            if (it.kind == ScreenItemKind::Text && it.typeSpeed > 0) {   // how long the typing takes
                size_t letters = 0; for (unsigned char c : it.text) if ((c & 0xC0) != 0x80) letters++;
                float te = X(it.showAt + letters / it.typeSpeed); dl->AddLine(ImVec2(a + 1, bot - 2), ImVec2(std::min(te, b), bot - 2), IM_COL32(255, 255, 255, 170), 2.f);
            }
            {   // what it is, on its bar
                std::string lab = it.kind == ScreenItemKind::Text ? it.text.substr(0, it.text.find('\n')) : it.kind == ScreenItemKind::Image ? it.image : it.kind == ScreenItemKind::Sound ? it.sound.file : it.name;
                if (lab.empty()) lab = it.name;
                dl->PushClipRect(ImVec2(std::max(a, x0) + 4, top), ImVec2(b - 2, bot), true);
                dl->AddText(ImVec2(std::max(a, x0) + 5, y + (rowH - ImGui::GetTextLineHeight()) * 0.5f), IM_COL32(255, 255, 255, 235), lab.c_str());
                dl->PopClipRect();
            }
            for (int k = 0; k < (int)it.keys.size(); k++) {   // keyframes
                float kx = X(it.keys[k].t), cy = y + rowH * 0.5f, r = rowH * 0.28f; bool ks = sel && k == tlKeySel;
                ImVec2 pts[4] = { ImVec2(kx, cy - r), ImVec2(kx + r, cy), ImVec2(kx, cy + r), ImVec2(kx - r, cy) };
                dl->AddConvexPolyFilled(pts, 4, ks ? IM_COL32(255, 210, 80, 255) : IM_COL32(245, 245, 250, 255)); dl->AddPolyline(pts, 4, IM_COL32(0, 0, 0, 200), ImDrawFlags_Closed, 1.f);
            }
            dl->PopClipRect(); dl->PopClipRect();
        }
        if (n == 0) dl->AddText(ImVec2(o.x + 10, o.y + rulerH + 8), IM_COL32(150, 155, 165, 255), "Nothing yet: add a text, a picture or a sound at the playhead (above), or an item (right).");
        dl->AddLine(ImVec2(x0, o.y), ImVec2(x0, o.y + sz.y), IM_COL32(255, 255, 255, 30));
        if (sc.duration > 0 && X(sc.duration) >= x0 && X(sc.duration) <= x1) {   // the screen's end
            float ex = X(sc.duration); dl->AddLine(ImVec2(ex, o.y), ImVec2(ex, o.y + sz.y), IM_COL32(255, 90, 80, 220), 2.f);
            dl->AddTriangleFilled(ImVec2(ex - 6, o.y), ImVec2(ex + 6, o.y), ImVec2(ex, o.y + 9), IM_COL32(255, 90, 80, 255));
        }
        {   // the playhead
            float px = X((float)scrPlayT);
            if (px >= x0 && px <= x1) { dl->AddLine(ImVec2(px, o.y), ImVec2(px, o.y + sz.y), IM_COL32(255, 210, 70, 255), 1.5f); dl->AddRectFilled(ImVec2(px - 5, o.y), ImVec2(px + 5, o.y + rulerH * 0.55f), IM_COL32(255, 210, 70, 255), 2.f); }
        }
        dl->PopClipRect();

        // ---- the mouse: what is under it
        auto rowAt = [&](float my) { if (my < o.y + rulerH) return -2; int r = (int)std::floor((my - o.y - rulerH + tlRowScroll) / rowH); return r >= 0 && r < n ? r : -1; };
        int hr = hov ? rowAt(mp.y) : -1; int hzone = 0, hkey = -1;   // 1 the bar, 2 its start, 3 its end, 4 a key
        if (hr >= 0 && mp.x >= x0) {
            const ScreenItem& it = sc.items[hr]; float a = X(it.showAt), b = X(itemEnd(it, len));
            for (int k = 0; k < (int)it.keys.size(); k++) if (std::fabs(mp.x - X(it.keys[k].t)) < rowH * 0.3f) { hzone = 4; hkey = k; }
            if (!hzone) { if (std::fabs(mp.x - a) < 5) hzone = 2; else if (std::fabs(mp.x - b) < 5 && it.kind != ScreenItemKind::Sound) hzone = 3; else if (mp.x > a && mp.x < b) hzone = 1; }
            if (hzone == 2 || hzone == 3) ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeEW);
            if (hzone && stDrag == 0) {
                char tip[200]; float e = itemEnd(it, len);
                if (hzone == 4) snprintf(tip, sizeof tip, "Keyframe at %.2f s\nDrag: move it   Right-click: delete", it.keys[hkey].t);
                else snprintf(tip, sizeof tip, "%s\n%.2f s - %s\nDrag to move it, its ends to change them. Right-click: more", it.name.c_str(), it.showAt, it.hideAt > 0 || it.kind == ScreenItemKind::Sound ? (std::to_string(e).substr(0, std::to_string(e).find('.') + 3) + " s").c_str() : "stays");
                ImGui::SetTooltip("%s", tip);
            }
        }
        bool nearEnd = hov && sc.duration > 0 && std::fabs(mp.x - X(sc.duration)) < 6 && (hr == -2 || hzone == 0);
        if (nearEnd) { ImGui::SetMouseCursor(ImGuiMouseCursor_ResizeEW); if (stDrag == 0) ImGui::SetTooltip("The screen's end (%.2f s): it goes on to the next. Drag to change.", sc.duration); }
        if (hov && ImGui::IsMouseClicked(0)) {
            stDrag = 0; tlDragItem = hr; tlGrabT = T(mp.x);
            if (nearEnd) stDrag = 6;
            else if (hr == -2) { if (mp.x >= x0) { stDrag = 5; scrPlaying = false; } }
            else if (hr >= 0 && mp.x < x0) { scrItem = hr; tlKeySel = -1; }
            else if (hr >= 0) {
                ScreenItem& it = sc.items[hr]; scrItem = hr;
                if (hzone == 0) { stDrag = 5; scrPlaying = false; tlKeySel = -1; }
                else {
                    stDrag = hzone; tlDragKey = hkey; tlKeySel = hzone == 4 ? hkey : -1; tlOrigA = it.showAt; tlOrigB = it.hideAt;
                    tlOrigKeys.clear(); for (const ItemKey& k : it.keys) tlOrigKeys.push_back(k.t);
                }
            } else if (mp.x >= x0) { stDrag = 5; scrPlaying = false; }
        }
        if (stDrag && ImGui::IsMouseDown(0)) {
            float t = T(mp.x), d = t - tlGrabT; ScreenItem* it = tlDragItem >= 0 && tlDragItem < n ? &sc.items[tlDragItem] : nullptr;
            if (stDrag == 5) { scrPlayT = std::max(0.f, snap(t, -1)); scrPrevT = scrPlayT; }
            else if (stDrag == 6) { float v = std::max(0.1f, snap(t, -1)); if (v != sc.duration) { sc.duration = v; ch = true; } }
            else if (it && stDrag == 1) {   // the whole bar (its keys go along)
                float na = snap(tlOrigA + d, tlDragItem);
                if (it->hideAt > 0 && tlSnap && !io.KeyShift) { float nb = snap(tlOrigB + d, tlDragItem); if (std::fabs(X(nb) - X(tlOrigB + d)) < std::fabs(X(na) - X(tlOrigA + d))) na = nb - (tlOrigB - tlOrigA); }   // (its end can snap too)
                na = std::max(0.f, na); float dd = na - tlOrigA;
                it->showAt = na; if (tlOrigB > 0) it->hideAt = tlOrigB + dd;
                for (size_t k = 0; k < it->keys.size() && k < tlOrigKeys.size(); k++) it->keys[k].t = std::max(0.f, tlOrigKeys[k] + dd);
                ch = true;
            }
            else if (it && stDrag == 2) { float v = snap(t, tlDragItem); if (it->hideAt > 0) v = std::min(v, it->hideAt - 0.05f); it->showAt = std::max(0.f, v); ch = true; }
            else if (it && stDrag == 3) { it->hideAt = std::max(it->showAt + 0.05f, snap(t, tlDragItem)); ch = true; }
            else if (it && stDrag == 4 && tlDragKey >= 0 && tlDragKey < (int)it->keys.size()) {   // a key: between its neighbours
                float v = snap(t, tlDragItem);
                if (tlDragKey > 0) v = std::max(v, it->keys[tlDragKey - 1].t + 0.02f);
                if (tlDragKey + 1 < (int)it->keys.size()) v = std::min(v, it->keys[tlDragKey + 1].t - 0.02f);
                it->keys[tlDragKey].t = std::max(0.f, v); scrPlayT = it->keys[tlDragKey].t; scrPrevT = scrPlayT; ch = true;
            }
        }
        if (!ImGui::IsMouseDown(0)) stDrag = 0;
        // ---- right-click: more
        if (hov && ImGui::IsMouseClicked(1)) {
            tlDragItem = hr; tlDragKey = hkey;
            if (hr == -2 || (hr == -1 && mp.x >= x0)) { tlGrabT = T(mp.x); ImGui::OpenPopup("tlruler"); }
            else if (hr >= 0) { scrItem = hr; tlKeySel = hkey; ImGui::OpenPopup("tlitem"); }
        }
        if (ImGui::BeginPopup("tlruler")) {
            float t = snap(tlGrabT, -1);
            if (ImGui::Selectable(("The screen ends here (" + std::to_string(t).substr(0, std::to_string(t).find('.') + 3) + " s)").c_str())) { sc.duration = std::max(0.1f, t); ch = true; }
            if (ImGui::Selectable("It never ends by itself", sc.duration <= 0)) { sc.duration = 0; ch = true; }
            if (ImGui::Selectable("Playhead here")) { scrPlayT = t; scrPrevT = t; scrPlaying = false; }
            ImGui::EndPopup();
        }
        if (ImGui::BeginPopup("tlitem")) {
            if (tlDragItem >= 0 && tlDragItem < (int)sc.items.size()) {
                ScreenItem& it = sc.items[tlDragItem]; float t = (float)scrPlayT;
                if (tlDragKey >= 0 && tlDragKey < (int)it.keys.size()) {
                    ItemKey& k = it.keys[tlDragKey];
                    if (ImGui::MenuItem("Smooth (eases in and out)", nullptr, k.smooth)) { k.smooth = !k.smooth; ch = true; }
                    if (ImGui::MenuItem("Delete this keyframe")) { it.keys.erase(it.keys.begin() + tlDragKey); tlKeySel = -1; ch = true; }
                    ImGui::Separator();
                }
                if (ImGui::MenuItem("Starts at the playhead")) { if (it.hideAt > 0 && t >= it.hideAt) it.hideAt = t + std::max(0.5f, it.hideAt - it.showAt); it.showAt = t; ch = true; }
                if (it.kind != ScreenItemKind::Sound) {
                    if (ImGui::MenuItem("Ends at the playhead", nullptr, false, t > it.showAt)) { it.hideAt = t; ch = true; }
                    if (ImGui::MenuItem("Stays (no end)", nullptr, it.hideAt <= 0)) { it.hideAt = 0; ch = true; }
                    ImGui::Separator();
                    if (ImGui::MenuItem("Keyframe here (where it is now)")) { ItemPose p = itemPose(it, t); ItemKey k; k.t = t; k.x = p.x; k.y = p.y; k.scale = p.scale; k.alpha = p.alpha; setKey(it, k); ch = true; }
                    if (!it.keys.empty() && ImGui::MenuItem("Remove all its keyframes")) { ItemPose p = itemPose(it, t); it.x = p.x; it.y = p.y; it.keys.clear(); tlKeySel = -1; ch = true; }
                }
                ImGui::Separator();
                if (ImGui::MenuItem("Copy")) { ScreenItem c = it; c.name += " copy"; sc.items.push_back(c); scrItem = (int)sc.items.size() - 1; ch = true; }
                if (ImGui::MenuItem("Delete")) { sc.items.erase(sc.items.begin() + tlDragItem); scrItem = -1; tlKeySel = -1; ch = true; }
            }
            ImGui::EndPopup();
        }
        ImGui::EndChild();
    }
    // ---- the stack (intros): steps one after another - a picture (stays / zooms in), a text typed, a wait, a sound, clear
    int stackSel = -1;
    static ImU32 StepColor(StepKind k) { return k == StepKind::Picture ? IM_COL32(69, 184, 132, 255) : k == StepKind::Text ? IM_COL32(76, 141, 255, 255) : k == StepKind::Sound ? IM_COL32(168, 117, 240, 255) : k == StepKind::Clear ? IM_COL32(140, 140, 150, 255) : IM_COL32(200, 160, 70, 255); }
    std::string StepSummary(const StackStep& s) {
        switch (s.kind) {
        case StepKind::Picture: return (s.file.empty() ? std::string("(pick a picture)") : s.file) + (s.zoom ? "  -  zooms in" : "  -  stays");
        case StepKind::Text: { std::string t = s.text.substr(0, s.text.find('\n')); if (t.size() < s.text.size()) t += " ..."; return (t.empty() ? "(no text yet)" : t) + (s.keep ? "   (with the text before)" : ""); }
        case StepKind::Wait: { char b[32]; snprintf(b, sizeof b, "%.1f s", s.hold); return b; }
        case StepKind::Sound: return s.sound.empty() ? "(pick a sound)" : s.sound.file;
        case StepKind::Clear: return "everything fades away";
        default: return "";
        }
    }
    StackStep NewStep(const mc::Screen& sc, StepKind k, int after) {   // a new step: a text looks like the text before it
        StackStep s; s.kind = k;
        if (k == StepKind::Text) {
            s.text = "New text";
            for (int i = std::min(after, (int)sc.stack.size() - 1); i >= 0; i--) if (sc.stack[i].kind == StepKind::Text) { const StackStep& p = sc.stack[i]; s.place = p.place; s.typeSpeed = p.typeSpeed; s.sound = p.sound; s.hold = p.hold; s.textSize = p.textSize; s.color = p.color; s.align = p.align; break; }
        }
        if (k == StepKind::Wait) s.hold = 1.5f;
        if (k == StepKind::Sound) s.hold = 0;
        if (k == StepKind::Clear) s.fade = 1;
        return s;
    }
    void StackChanged(mc::Screen& sc, bool& ch) { sc.duration = buildStack(sc.stack).length; ch = true; }
    void ScreenStack(mc::Screen& sc, bool& ch, float height) {
        float ui = settings.uiScale; StackBuild bd = buildStack(sc.stack);
        if (sc.duration != bd.length) { sc.duration = bd.length; ch = true; }
        stackSel = std::min(stackSel, (int)sc.stack.size() - 1);
        // ---- above: play, back to the start, the time, adding steps
        if (ImGui::Button(scrPlaying ? "Pause" : "Play", ImVec2(64 * ui, 0))) {
            scrPlaying = !scrPlaying; scrAudible = scrPlaying;
            if (scrPlaying) { if (scrPlayT >= bd.length) scrPlayT = 0; scrPrevT = scrPlayT - 0.001; scrTyped.clear(); }
        }
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("Play it from where it is, with its sounds.");
        ImGui::SameLine(); if (ImGui::Button("|<")) { scrPlayT = 0; scrPrevT = -1; scrTyped.clear(); }
        ImGui::SameLine(); ImGui::AlignTextToFramePadding(); ImGui::Text("%5.1f s", scrPlayT); ImGui::SameLine(); ImGui::TextDisabled("of %.1f s", bd.length);
        int at = stackSel >= 0 ? stackSel + 1 : (int)sc.stack.size();   // new steps go after the picked one
        for (StepKind k : { StepKind::Picture, StepKind::Text, StepKind::Wait, StepKind::Sound, StepKind::Clear }) {
            ImGui::SameLine(); std::string l = std::string("+ ") + stepKindName(k);
            ImGui::PushStyleColor(ImGuiCol_Button, ImGui::ColorConvertU32ToFloat4((StepColor(k) & 0x00FFFFFF) | 0x80000000));
            if (ImGui::Button(l.c_str())) { sc.stack.insert(sc.stack.begin() + at, NewStep(sc, k, at - 1)); stackSel = at; scrItem = -1; StackChanged(sc, ch); bd = buildStack(sc.stack); scrPlayT = bd.starts[at]; scrPlaying = false; }
            ImGui::PopStyleColor();
        }
        ImGui::SameLine(); ImGui::TextDisabled("(after the picked step)");
        // ---- the list
        float h = std::max(80.f, height - ImGui::GetFrameHeightWithSpacing() - 2);
        ImGui::BeginChild("stack", ImVec2(0, h), ImGuiChildFlags_Borders);
        ImDrawList* dl = ImGui::GetWindowDrawList(); float rowH = 42 * ui, w = ImGui::GetContentRegionAvail().x;
        int drop = -1, moveFrom = -1, moveTo = -1, dup = -1;
        int playing = -1; for (int i = 0; i < (int)bd.starts.size(); i++) if (scrPlayT >= bd.starts[i]) playing = i;
        for (int i = 0; i < (int)sc.stack.size(); i++) {
            StackStep& st = sc.stack[i]; ImGui::PushID(i);
            ImVec2 p = ImGui::GetCursorScreenPos(); bool picked = i == stackSel;
            ImGui::InvisibleButton("##step", ImVec2(w - 3 * ImGui::GetFrameHeight() - 20 * ui, rowH));
            bool hov = ImGui::IsItemHovered();
            if (ImGui::IsItemClicked()) {   // picked: the preview shows it (whole: faded in, typed)
                stackSel = i; scrItem = -1; scrPlaying = false;
                float show = bd.starts[i] + (st.kind == StepKind::Picture ? st.fade + (st.zoom ? st.zoomTime : 0) : st.kind == StepKind::Text ? (st.typeSpeed > 0 ? (float)st.text.size() / st.typeSpeed : 0) + 0.6f : 0.05f);
                scrPlayT = std::min(show, (i + 1 < (int)bd.starts.size() ? bd.starts[i + 1] : bd.length) - 0.05f); scrPrevT = scrPlayT;
            }
            if (ImGui::BeginDragDropSource()) { ImGui::SetDragDropPayload("PRIM_STEP", &i, sizeof i); ImGui::Text("%d. %s", i + 1, stepKindName(st.kind)); ImGui::EndDragDropSource(); }
            if (ImGui::BeginDragDropTarget()) { if (const ImGuiPayload* pl = ImGui::AcceptDragDropPayload("PRIM_STEP")) { moveFrom = *(const int*)pl->Data; moveTo = i; } ImGui::EndDragDropTarget(); }
            if (ImGui::BeginPopupContextItem("##sctx")) {
                if (ImGui::MenuItem("Duplicate")) dup = i;
                if (ImGui::MenuItem("Delete")) drop = i;
                ImGui::EndPopup();
            }
            ImVec2 b(p.x + w - 3 * ImGui::GetFrameHeight() - 20 * ui, p.y + rowH);
            dl->AddRectFilled(p, b, picked ? IM_COL32(60, 85, 135, 230) : hov ? IM_COL32(52, 56, 66, 255) : IM_COL32(40, 43, 50, 255), 5.f);
            if (i == playing && scrPlaying) dl->AddRect(p, b, IM_COL32(255, 210, 70, 220), 5.f, 0, 2.f);
            dl->AddRectFilled(p, ImVec2(p.x + 5 * ui, b.y), StepColor(st.kind), 5.f, ImDrawFlags_RoundCornersLeft);
            float th = rowH - 8; ImVec2 tp(p.x + 12 * ui, p.y + 4);   // a little picture of the step
            dl->AddRectFilled(tp, ImVec2(tp.x + th * 1.5f, tp.y + th), IM_COL32(18, 20, 26, 255), 3.f);
            if (st.kind == StepKind::Picture && !st.file.empty()) { int iw = 0, ih = 0; ID3D11ShaderResourceView* im = PictureAt(st.file, uiClock, true, &iw, &ih); if (im && iw > 0 && ih > 0) { float k = std::min(th * 1.5f / iw, th / (float)ih), ww = iw * k, hh = ih * k; ImVec2 a(tp.x + (th * 1.5f - ww) * 0.5f, tp.y + (th - hh) * 0.5f); dl->AddImage((ImTextureID)(intptr_t)im, a, ImVec2(a.x + ww, a.y + hh)); } }
            else {
                const char* glyph = st.kind == StepKind::Text ? "Aa" : st.kind == StepKind::Wait ? "..." : st.kind == StepKind::Sound ? "~))" : st.kind == StepKind::Clear ? "fade" : "?";
                ImVec2 gs = ImGui::CalcTextSize(glyph); dl->AddText(ImVec2(tp.x + (th * 1.5f - gs.x) * 0.5f, tp.y + (th - gs.y) * 0.5f), StepColor(st.kind), glyph);
            }
            float tx = tp.x + th * 1.5f + 10 * ui;
            char head[64]; snprintf(head, sizeof head, "%d.  %s", i + 1, stepKindName(st.kind));
            dl->AddText(ImVec2(tx, p.y + 4), IM_COL32(235, 238, 245, 255), head);
            char when[48]; snprintf(when, sizeof when, "at %.1f s", i < (int)bd.starts.size() ? bd.starts[i] : 0.f);
            ImVec2 ws = ImGui::CalcTextSize(when); dl->AddText(ImVec2(b.x - ws.x - 8, p.y + 4), IM_COL32(150, 155, 168, 255), when);
            dl->PushClipRect(ImVec2(tx, p.y), ImVec2(b.x - 8, b.y), true);
            dl->AddText(ImVec2(tx, p.y + 4 + ImGui::GetTextLineHeight() + 2), IM_COL32(170, 178, 192, 255), StepSummary(st).c_str());
            dl->PopClipRect();
            ImGui::SameLine(); ImGui::BeginGroup();
            ImGui::BeginDisabled(i == 0); if (ImGui::ArrowButton("##u", ImGuiDir_Up)) { moveFrom = i; moveTo = i - 1; } ImGui::EndDisabled();
            ImGui::SameLine(); ImGui::BeginDisabled(i + 1 >= (int)sc.stack.size()); if (ImGui::ArrowButton("##d", ImGuiDir_Down)) { moveFrom = i; moveTo = i + 1; } ImGui::EndDisabled();
            ImGui::SameLine(); if (ImGui::Button("x", ImVec2(ImGui::GetFrameHeight(), 0))) drop = i;
            ImGui::EndGroup();
            ImGui::PopID();
        }
        if (sc.stack.empty()) Hint("An empty stack. Add steps above: a picture (it stays, or zooms in slowly), a text typed under it, a wait, a sound, or clear (all fades away). They play one after another, top to bottom; a new picture starts a new page.");
        ImGui::EndChild();
        if (moveFrom >= 0 && moveTo >= 0 && moveFrom != moveTo && moveFrom < (int)sc.stack.size() && moveTo < (int)sc.stack.size()) {
            StackStep s = sc.stack[moveFrom]; sc.stack.erase(sc.stack.begin() + moveFrom); sc.stack.insert(sc.stack.begin() + moveTo, s);
            if (stackSel == moveFrom) stackSel = moveTo; StackChanged(sc, ch);
        }
        if (dup >= 0) { sc.stack.insert(sc.stack.begin() + dup + 1, sc.stack[dup]); stackSel = dup + 1; StackChanged(sc, ch); }
        if (drop >= 0) { sc.stack.erase(sc.stack.begin() + drop); if (stackSel >= drop) stackSel--; StackChanged(sc, ch); }
    }
    bool TextLookUI(float& weight, float& outline, uint32_t& outlineColor) {   // thickness and outline (texts, buttons, credits, stack texts)
        bool c = false;
        Prop("Thickness"); c |= ImGui::SliderFloat("##tlw", &weight, 0, 1, weight <= 0 ? "normal" : "%.2f");
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("Thicker letters (0: as the font is).");
        Prop("Outline"); c |= ImGui::SliderFloat("##tlo", &outline, 0, 1, outline <= 0 ? "none" : "%.2f");
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("A line all around the outside of the letters (the letters stay whole, it is not drawn over them).");
        if (outline > 0) { Prop("Outline colour"); c |= ColorU32("##tloc", outlineColor); }
        return c;
    }
    void StepProps(mc::Screen& sc, StackStep& s, bool& ch) {
        bool c = false; float ui = settings.uiScale;
        Prop("Step"); int k = (int)s.kind;
        if (ImGui::BeginCombo("##stk", stepKindName(s.kind))) { for (int i = 0; i < (int)StepKind::COUNT; i++) if (ImGui::Selectable(stepKindName((StepKind)i), i == k)) { s.kind = (StepKind)i; c = true; } ImGui::EndCombo(); }
        switch (s.kind) {
        case StepKind::Picture: {
            Prop("Picture"); c |= FileCombo("##stf", s.file, false);
            Prop("It"); int z = s.zoom ? 1 : 0; const char* zz[] = { "Stays", "Zooms in slowly" }; if (ImGui::Combo("##stz", &z, zz, 2)) { s.zoom = z == 1; c = true; }
            if (s.zoom) { Prop("  closer, to"); c |= ImGui::SliderFloat("##stzt", &s.zoomTo, 1.02f, 3, "x %.2f"); Prop("  over"); c |= ImGui::SliderFloat("##stzs", &s.zoomTime, 0.5f, 20, "%.1f s"); }
            Prop("Fades in over"); c |= ImGui::SliderFloat("##stfd", &s.fade, 0.05f, 4, "%.1f s");
            Prop("Where"); const char* pl[] = { "The whole screen", "The top part (text under it)", "The middle (a logo)" }; c |= ImGui::Combo("##stpl", &s.place, pl, 3);
            Hint(s.zoom ? "It fades in and slowly zooms in; the next step starts when the zoom is done." : "It fades in and stays; the next step (a text, say) starts right after it faded in.");
            Hint("A picture starts a new page: the picture and text before it fade away as it comes.");
            break; }
        case StepKind::Text: {
            ImGui::TextDisabled("Says"); c |= ImGui::InputTextMultiline("##stt", &s.text, ImVec2(-1, 90 * ui));
            if (ImGui::IsItemHovered()) ImGui::SetTooltip("{game} {world} are filled in. New lines stay; long lines wrap.");
            Prop("Typed"); c |= ImGui::SliderFloat("##stts", &s.typeSpeed, 0, 80, s.typeSpeed <= 0 ? "all at once" : "%.0f letters/s");
            if (s.typeSpeed > 0) { Prop("Letter sound"); c |= SoundEdit("##stsn", s.sound, false); }
            Prop("Fades in over"); c |= ImGui::SliderFloat("##sttf", &s.textFade, 0.02f, 4, "%.2f s");
            Prop("Stays for"); c |= ImGui::SliderFloat("##sth", &s.hold, 0, 15, s.typeSpeed > 0 ? "%.1f s once typed" : "%.1f s once there");
            Prop("Where"); const char* pl[] = { "Bottom", "Middle", "Top", "Under the middle (a line under a title)" }; c |= ImGui::Combo("##stpl", &s.place, pl, 4);
            Prop("Comes with the text before"); c |= ImGui::Checkbox("##stk2", &s.keep);
            if (ImGui::IsItemHovered()) ImGui::SetTooltip("On: the text before stays (a title and a line under it: put them in different places).\nOff: it replaces the text before.");
            Prop("Size"); c |= ImGui::SliderFloat("##stsz", &s.textSize, 0.015f, 0.12f, "%.3f");
            Prop("Colour"); c |= ColorU32("##stc", s.color);
            Prop("Lined up"); const char* al[] = { "Left", "Middle", "Right" }; c |= ImGui::Combo("##sta", &s.align, al, 3);
            c |= TextLookUI(s.weight, s.outline, s.outlineColor);
            Hint(s.typeSpeed > 0 ? "It is typed letter by letter, stays a while, then the next step. A new text replaces this one (it fades first), unless the new one comes with it." : "It fades in, stays a while, then the next step. A new text replaces this one, unless the new one comes with it.");
            break; }
        case StepKind::Wait: Prop("Waits"); c |= ImGui::SliderFloat("##stw", &s.hold, 0, 20, "%.1f s"); Hint("Nothing new for a while: what is there stays."); break;
        case StepKind::Sound: Prop("Sound"); c |= SoundEdit("##sts", s.sound, false); Prop("Then waits"); c |= ImGui::SliderFloat("##stw", &s.hold, 0, 20, "%.1f s"); Hint("It plays, and the next step starts after the wait (0: right away, while it plays)."); break;
        case StepKind::Clear: Prop("Fades away over"); c |= ImGui::SliderFloat("##stcf", &s.fade, 0.05f, 5, "%.1f s"); Hint("The picture and text that are there fade away (to the background)."); break;
        default: break;
        }
        if (c) StackChanged(sc, ch);
    }
    void ScreenLayoutTab(mc::Screen& sc, bool& ch) {
        float ui = settings.uiScale, propW = 340 * ui, sp = ImGui::GetStyle().ItemSpacing.x;
        float aw = std::max(200.f, ImGui::GetContentRegionAvail().x - propW - sp), ah = ImGui::GetContentRegionAvail().y;
        ImGui::BeginChild("scrcanvas", ImVec2(aw, ah), ImGuiChildFlags_None, ImGuiWindowFlags_NoScrollbar);
        {   // the canvas: the screen as it will look at the playhead; click an item to pick it, drag to move, the corner to resize
            float aspect = (float)std::max(1, cw) / std::max(1, ch_());
            float w = aw, h = w / aspect; if (h > ah * 0.58f) { h = ah * 0.58f; w = h * aspect; }
            ImVec2 o = ImGui::GetCursorScreenPos(); ScreenPreviewImage(w, h);
            ImDrawList* dl = ImGui::GetWindowDrawList(); ImGuiIO& io = ImGui::GetIO();
            ImGui::SetCursorScreenPos(o); ImGui::InvisibleButton("##scrcv", ImVec2(w, h));
            bool hov = ImGui::IsItemHovered(); ImVec2 m((io.MousePos.x - o.x) / w, (io.MousePos.y - o.y) / h);
            float t = (float)scrPlayT;
            auto rectOf = [&](const ScreenItem& it, ImVec2& a, ImVec2& b) {   // where it shows at the playhead (0..1)
                ItemPose p = itemPose(it, t); float age = std::max(0.f, t - it.showAt), k = (1 + it.grow * age) * std::max(0.01f, p.scale);
                float cx = p.x + it.w * 0.5f + it.driftX * age, cy = p.y + it.h * 0.5f + it.driftY * age;
                a = ImVec2(cx - it.w * 0.5f * k, cy - it.h * 0.5f * k); b = ImVec2(cx + it.w * 0.5f * k, cy + it.h * 0.5f * k);
            };
            auto there = [&](int i) { const ScreenItem& it = sc.items[i]; return it.kind != ScreenItemKind::Sound && (i == scrItem || itemShown(it, t) > 0.002f); };
            for (int i = 0; i < (int)sc.items.size(); i++) {
                if (!there(i)) continue;
                const ScreenItem& it = sc.items[i]; ImVec2 ra, rb; rectOf(it, ra, rb); ImVec2 a(o.x + ra.x * w, o.y + ra.y * h), b(o.x + rb.x * w, o.y + rb.y * h);
                bool picked = i == scrItem, gone = itemShown(it, t) <= 0.002f;
                dl->AddRect(a, b, picked ? IM_COL32(255, 200, 60, gone ? 110 : 255) : IM_COL32(255, 255, 255, 50), 0.f, ImDrawFlags_None, picked ? 2.f : 1.f);
                if (picked) dl->AddRectFilled(ImVec2(b.x - 7, b.y - 7), ImVec2(b.x + 1, b.y + 1), IM_COL32(255, 200, 60, 255));
                if (picked && !it.keys.empty()) dl->AddText(ImVec2(a.x + 3, a.y + 2), IM_COL32(255, 200, 60, 230), "keyframes");
            }
            if (hov && ImGui::IsMouseClicked(0)) {
                scrDragMode = 0;
                if (scrItem >= 0 && scrItem < (int)sc.items.size() && there(scrItem)) {   // the picked one's corner: resize
                    ImVec2 ra, rb; rectOf(sc.items[scrItem], ra, rb);
                    if (std::fabs(m.x - rb.x) * w < 9 && std::fabs(m.y - rb.y) * h < 9) scrDragMode = 2;
                }
                if (!scrDragMode) {
                    scrItem = -1;
                    for (int i = (int)sc.items.size() - 1; i >= 0; i--) { if (!there(i) || itemShown(sc.items[i], t) <= 0.002f) continue; ImVec2 ra, rb; rectOf(sc.items[i], ra, rb); if (m.x >= ra.x && m.x <= rb.x && m.y >= ra.y && m.y <= rb.y) { scrItem = i; break; } }
                    if (scrItem >= 0) scrDragMode = 1;
                }
                if (scrItem >= 0) {
                    const ScreenItem& it = sc.items[scrItem]; ItemPose p = itemPose(it, t);
                    scrDragX = m.x; scrDragY = m.y; scrOrig[0] = p.x; scrOrig[1] = p.y; scrOrig[2] = it.w; scrOrig[3] = it.h; scrOrig[4] = p.scale; scrOrig[5] = p.alpha;
                    if (!it.keys.empty()) scrPlaying = false;   // (moving it makes a keyframe here: hold still)
                }
            }
            if (scrDragMode && ImGui::IsMouseDown(0) && scrItem >= 0 && scrItem < (int)sc.items.size()) {
                ScreenItem& it = sc.items[scrItem]; float dx = m.x - scrDragX, dy = m.y - scrDragY;
                if (dx != 0 || dy != 0) {
                    bool keyed = !it.keys.empty();
                    if (scrDragMode == 1) {
                        float nx = scrOrig[0] + dx, ny = scrOrig[1] + dy;
                        if (io.KeyCtrl) { nx = std::round(nx * 40) / 40; ny = std::round(ny * 40) / 40; }   // Ctrl: on a grid
                        if (keyed) { ItemKey k; k.t = t; k.x = nx; k.y = ny; k.scale = scrOrig[4]; k.alpha = scrOrig[5]; for (const ItemKey& e : it.keys) if (std::fabs(e.t - t) < 0.02f) k.smooth = e.smooth; setKey(it, k); }
                        else { it.x = nx; it.y = ny; }
                    } else if (keyed) {   // resizing an animated one: its size at the playhead
                        ItemKey k; k.t = t; k.x = scrOrig[0]; k.y = scrOrig[1]; k.scale = std::max(0.05f, scrOrig[4] + dx / std::max(0.01f, it.w)); k.alpha = scrOrig[5];
                        for (const ItemKey& e : it.keys) if (std::fabs(e.t - t) < 0.02f) k.smooth = e.smooth; setKey(it, k);
                    } else {
                        float nw = scrOrig[2] + dx, nh = scrOrig[3] + dy;
                        if (io.KeyCtrl) { nw = std::round(nw * 40) / 40; nh = std::round(nh * 40) / 40; }
                        it.w = std::max(0.01f, nw); it.h = std::max(0.01f, nh);
                    }
                    ch = true;
                }
            }
            if (!ImGui::IsMouseDown(0)) scrDragMode = 0;
            ImGui::SetCursorScreenPos(ImVec2(o.x, o.y + h + 4));
            ImGui::TextDisabled("The screen at the playhead. Click to pick, drag to move, the corner resizes (Ctrl: on a grid). An item with keyframes gets a keyframe where you drag it.");
        }
        {   // made as a stack (steps one after another) or on a timeline (every item where you put it)
            int m = sc.useStack ? 0 : 1; ImGui::AlignTextToFramePadding(); ImGui::TextDisabled("Made as"); ImGui::SameLine();
            bool chm = ImGui::RadioButton("a stack", &m, 0); if (ImGui::IsItemHovered()) ImGui::SetTooltip("Steps one after another (pictures, texts, waits, sounds): the timing works itself out. For intros.");
            ImGui::SameLine(); chm |= ImGui::RadioButton("a timeline", &m, 1); if (ImGui::IsItemHovered()) ImGui::SetTooltip("Every item on a timeline, where you put it, with keyframes. For splash screens and anything free.");
            if (chm && sc.useStack != (m == 0)) {
                sc.useStack = m == 0;
                if (sc.useStack && sc.stack.empty()) {   // its texts, pictures and sounds become steps (at about the same times)
                    size_t before = sc.items.size(); sc.stack = stepsFromItems(sc.items); scrItem = -1;
                    if (!sc.stack.empty()) Toast("Its " + std::to_string(before - sc.items.size()) + " texts, pictures and sounds became steps" + (sc.items.empty() ? "" : " (the rest stays as items)"));
                }
                if (sc.useStack) sc.duration = buildStack(sc.stack).length;
                stackSel = -1; scrPlayT = 0; scrPrevT = -1; ch = true;
            }
        }
        if (sc.useStack) ScreenStack(sc, ch, ImGui::GetContentRegionAvail().y); else ScreenTimeline(sc, ch, ImGui::GetContentRegionAvail().y);
        ImGui::EndChild();
        ImGui::SameLine();
        ImGui::BeginChild("scrprops", ImVec2(propW, ah), ImGuiChildFlags_Borders);
        if (ImGui::Button("+ Item")) ImGui::OpenPopup("additem");
        if (ImGui::BeginPopup("additem")) {
            for (int k = 0; k < (int)ScreenItemKind::COUNT; k++) if (ImGui::Selectable(screenItemKindName((ScreenItemKind)k))) {
                ScreenItem it; it.kind = (ScreenItemKind)k; it.name = screenItemKindName(it.kind); it.x = 0.35f; it.y = 0.4f;
                if (it.kind == ScreenItemKind::Text) it.text = "Text";
                if (it.kind == ScreenItemKind::Button) { it.text = "Button"; it.h = 0.07f; it.textSize = 0.036f; }
                if (it.kind == ScreenItemKind::Options) { it.x = 0.1f; it.y = 0.15f; it.w = 0.8f; it.h = 0.7f; it.textSize = 0.032f; }
                if (it.kind == ScreenItemKind::SaveSlots) { it.x = 0.1f; it.y = 0.18f; it.w = 0.8f; it.h = 0.6f; it.textSize = 0.034f; }
                if (it.kind == ScreenItemKind::Credits) { it.text = "# Thanks\nfor playing"; it.y = 0.1f; it.w = 0.5f; it.h = 0.8f; it.x = 0.25f; }
                if (it.kind == ScreenItemKind::Panel || it.kind == ScreenItemKind::Image) { it.w = 0.3f; it.h = 0.3f; }
                sc.items.push_back(it); scrItem = (int)sc.items.size() - 1; ch = true;
            }
            ImGui::EndPopup();
        }
        if (scrItem >= 0 && scrItem < (int)sc.items.size()) {
            ImGui::SameLine(); if (ImGui::ArrowButton("##up", ImGuiDir_Up) && scrItem > 0) { std::swap(sc.items[scrItem], sc.items[scrItem - 1]); scrItem--; ch = true; }
            ImGui::SameLine(); if (ImGui::ArrowButton("##dn", ImGuiDir_Down) && scrItem + 1 < (int)sc.items.size()) { std::swap(sc.items[scrItem], sc.items[scrItem + 1]); scrItem++; ch = true; }
            ImGui::SameLine(); if (ImGui::Button("Copy##it")) { ScreenItem c = sc.items[scrItem]; c.name += " copy"; c.x += 0.02f; c.y += 0.02f; sc.items.push_back(c); scrItem = (int)sc.items.size() - 1; ch = true; }
            ImGui::SameLine(); if (ImGui::Button("Delete##it")) { sc.items.erase(sc.items.begin() + scrItem); scrItem = -1; ch = true; }
        }
        ImGui::Separator();
        if (scrItem >= 0 && scrItem < (int)sc.items.size()) ScreenItemProps(sc.items[scrItem], ch);
        else if (sc.useStack && stackSel >= 0 && stackSel < (int)sc.stack.size()) { ImGui::SeparatorText(("Step " + std::to_string(stackSel + 1)).c_str()); StepProps(sc, sc.stack[stackSel], ch); }
        else ImGui::TextDisabled(sc.useStack ? "Pick a step in the stack (or an item on the canvas)." : "Pick an item (on the canvas or in the list).");
        ImGui::EndChild();
    }
    int ch_() const { return ch; }
    void ScreenItemProps(ScreenItem& it, bool& ch) {
        float ui = settings.uiScale;
        Prop("Name"); ch |= ImGui::InputText("##sin", &it.name);
        Prop("Kind"); if (ImGui::BeginCombo("##sik", screenItemKindName(it.kind))) { for (int k = 0; k < (int)ScreenItemKind::COUNT; k++) if (ImGui::Selectable(screenItemKindName((ScreenItemKind)k), (int)it.kind == k)) { it.kind = (ScreenItemKind)k; ch = true; } ImGui::EndCombo(); }
        if (it.kind == ScreenItemKind::Sound) {   // a sound cue: what, and when
            Prop("Sound"); ch |= SoundEdit("##sisnd", it.sound, false);
            Prop("Plays at"); ch |= ImGui::DragFloat("##sisat", &it.showAt, 0.01f, 0, 600, "%.2f s");
            Hint("It plays once when its time comes (drag its bar on the timeline). Press Play below the canvas to hear it with the rest.");
            return;
        }
        if (!it.keys.empty()) Hint("Its place, size and see-through come from its keyframes (below). Place / Size here: its size without them.");
        Prop("Place"); { float v[2] = { it.x, it.y }; if (ImGui::DragFloat2("##sip", v, 0.002f, -0.5f, 1.5f, "%.3f")) { it.x = v[0]; it.y = v[1]; ch = true; } }
        Prop("Size"); { float v[2] = { it.w, it.h }; if (ImGui::DragFloat2("##sis", v, 0.002f, 0.01f, 2, "%.3f")) { it.w = v[0]; it.h = v[1]; ch = true; } }
        bool hasText = it.kind == ScreenItemKind::Text || it.kind == ScreenItemKind::Button || it.kind == ScreenItemKind::Credits;
        if (hasText) {
            Prop(it.kind == ScreenItemKind::Credits ? "The roll" : "Says");
            if (it.kind == ScreenItemKind::Button) ch |= ImGui::InputText("##sit", &it.text); else ch |= ImGui::InputTextMultiline("##sit", &it.text, ImVec2(-1, (it.kind == ScreenItemKind::Credits ? 160 : 60) * ui));
            if (ImGui::IsItemHovered()) ImGui::SetTooltip("{game} {world} are filled in.%s", it.kind == ScreenItemKind::Credits ? "\nA line starting with \"# \" is a heading." : "");
        }
        if (it.kind != ScreenItemKind::Panel && it.kind != ScreenItemKind::Image) { Prop("Text size"); ch |= ImGui::SliderFloat("##sitz", &it.textSize, 0.01f, 0.2f, "%.3f of the height"); }
        if (hasText) { const char* al[] = { "Left", "Middle", "Right" }; Prop("Lined up"); ch |= ImGui::Combo("##sia", &it.align, al, 3); }
        if (it.kind == ScreenItemKind::Text) { const char* va[] = { "Top", "Middle", "Bottom" }; Prop("Up / down"); ch |= ImGui::Combo("##siva", &it.valign, va, 3); }
        if (hasText) ch |= TextLookUI(it.weight, it.outline, it.outlineColor);
        if (it.kind == ScreenItemKind::Image) { Prop("Picture"); ch |= FileCombo("##sii", it.image, false); }
        if (it.kind == ScreenItemKind::Button) {
            Prop("Does"); if (ImGui::BeginCombo("##siact", screenActName(it.act))) { for (int k = 0; k < (int)ScreenAct::COUNT; k++) if (ImGui::Selectable(screenActName((ScreenAct)k), (int)it.act == k)) { it.act = (ScreenAct)k; ch = true; } ImGui::EndCombo(); }
            if (it.act == ScreenAct::GoTo) { Prop("Screen"); if (ImGui::BeginCombo("##sitg", it.target.empty() ? "(pick one)" : it.target.c_str())) { for (const mc::Screen& s : screens.screens) if (ImGui::Selectable(s.name.c_str(), s.name == it.target)) { it.target = s.name; ch = true; } ImGui::EndCombo(); } }
            if (it.act == ScreenAct::Continue) Hint("Goes on from the newest save file (on the death screen: this file's last save). Greyed out while there is none.");
            if (it.act == ScreenAct::NewGame) Hint("Opens the Files screen (pick a file: an empty one starts a new game). Without a Files screen: a new game in File 1.");
        }
        if (it.kind == ScreenItemKind::Options) {
            const auto& gs = optionGroups(); int cur = 0; for (int k = 0; k < (int)gs.size(); k++) if (gs[k] == it.group) cur = k + 1;
            Prop("Shows"); if (ImGui::BeginCombo("##sio", cur ? gs[cur - 1].c_str() : "All three (as tabs)")) {
                if (ImGui::Selectable("All three (as tabs)", cur == 0)) { it.group.clear(); ch = true; }
                for (int k = 0; k < (int)gs.size(); k++) if (ImGui::Selectable(gs[k].c_str(), cur == k + 1)) { it.group = gs[k]; ch = true; }
                ImGui::EndCombo();
            }
        }
        if (it.kind == ScreenItemKind::Credits) { Prop("Speed"); ch |= ImGui::SliderFloat("##sisp", &it.speed, 0.005f, 0.3f, "%.3f screens/s"); }
        if (it.kind == ScreenItemKind::SaveSlots) { Prop("Files"); ch |= ImGui::SliderInt("##sisl", &it.slots, 1, 12); Hint("Picking an empty file starts a new game in it; a used one goes on from its last save. Delete twice erases one. Games save only at Save Stations."); }
        ImGui::SeparatorText("Colours");
        ScreenColors& c = it.col;
        if (it.kind != ScreenItemKind::Panel && it.kind != ScreenItemKind::Image) { Prop("Text"); ch |= ColorU32("##sct", c.text); }
        Prop("Accent"); ch |= ColorU32("##sca", c.accent);
        if (it.kind == ScreenItemKind::Button || it.kind == ScreenItemKind::Options) { Prop("Picked"); ch |= ColorU32("##scp", c.picked); Prop("Dim"); ch |= ColorU32("##scd", c.dim); }
        if (it.kind == ScreenItemKind::Panel || it.kind == ScreenItemKind::Button) {
            Prop("Fill"); ch |= ColorU32("##scf", c.fill); Prop("Fill strength"); ch |= ImGui::SliderFloat("##scfa", &c.fillAlpha, 0, 1, "%.2f");
            Prop("Filled"); ch |= ImGui::Checkbox("##sfl", &it.filled); ImGui::SameLine(); ImGui::TextUnformatted("Frame"); ImGui::SameLine(); ch |= ImGui::Checkbox("##sfr", &it.frame);
            Prop("Round corners"); ch |= ImGui::SliderFloat("##sro", &it.rounding, 0, 1, "%.2f"); Prop("Frame width"); ch |= ImGui::SliderFloat("##sbw", &it.border, 0.5f, 8, "%.1f px");
        }
        Prop("See-through"); { float op = 1 - it.alpha; if (ImGui::SliderFloat("##sial", &op, 0, 1, "%.2f")) { it.alpha = 1 - op; ch = true; } }
        ImGui::SeparatorText("Timing");
        Prop("Appears at"); ch |= ImGui::SliderFloat("##tsa", &it.showAt, 0, 60, it.showAt <= 0 ? "right away" : "%.1f s");
        Prop("Goes at"); ch |= ImGui::SliderFloat("##tha", &it.hideAt, 0, 60, it.hideAt <= 0 ? "stays" : "%.1f s");
        Prop("Fades in over"); ch |= ImGui::SliderFloat("##tfd", &it.fade, 0, 5, "%.2f s");
        Prop("Fades out over"); { float fo = it.fadeOutTime(); if (ImGui::SliderFloat("##tfo", &fo, 0, 5, "%.2f s")) { it.fadeOut = fo; ch = true; } }
        if (it.kind == ScreenItemKind::Text) {
            Prop("Typed"); ch |= ImGui::SliderFloat("##tty", &it.typeSpeed, 0, 80, it.typeSpeed <= 0 ? "all at once" : "%.0f letters/s");
            if (it.typeSpeed > 0) { Prop("Letter sound"); ch |= SoundEdit("##ttsnd", it.typeSound, false); }
        }
        Prop("Moves"); { float v[2] = { it.driftX, it.driftY }; if (ImGui::DragFloat2("##tdr", v, 0.0005f, -0.5f, 0.5f, "%.4f/s")) { it.driftX = v[0]; it.driftY = v[1]; ch = true; } }
        Prop("Grows"); ch |= ImGui::SliderFloat("##tgr", &it.grow, -0.2f, 0.5f, "%.3f/s");
        Hint("Seconds after the screen appears (the timeline under the canvas shows it all). For splash screens and intros (like Super Metroid's): fade text and pictures in and out, type a story letter by letter, let a picture slowly drift and grow.");
        ImGui::SeparatorText("Keyframes (moving over time)");
        {   float t = (float)scrPlayT; char kb[64]; snprintf(kb, sizeof kb, "+ Keyframe at the playhead (%.2f s)", t);
            if (ImGui::Button(kb)) { ItemPose p = itemPose(it, t); ItemKey k; k.t = t; k.x = p.x; k.y = p.y; k.scale = p.scale; k.alpha = p.alpha; setKey(it, k); ch = true; }
            int drop = -1;
            for (int k = 0; k < (int)it.keys.size(); k++) {
                ItemKey& key = it.keys[k]; ImGui::PushID(7000 + k);
                bool sel = k == tlKeySel; std::string hdr = (sel ? "> " : "") + std::to_string(key.t).substr(0, std::to_string(key.t).find('.') + 3) + " s###key";
                bool open = ImGui::TreeNodeEx(hdr.c_str(), sel ? ImGuiTreeNodeFlags_DefaultOpen : 0);
                ImGui::SameLine(); if (ImGui::SmallButton("go")) { scrPlayT = key.t; scrPrevT = key.t; scrPlaying = false; tlKeySel = k; }
                ImGui::SameLine(); if (ImGui::SmallButton("x")) drop = k;
                if (open) {
                    Prop("At"); if (ImGui::DragFloat("##kt", &key.t, 0.01f, 0, 600, "%.2f s")) { float v = key.t; ItemKey c = key; it.keys.erase(it.keys.begin() + k); c.t = v; setKey(it, c); ch = true; ImGui::TreePop(); ImGui::PopID(); break; }
                    Prop("Place"); { float v[2] = { key.x, key.y }; if (ImGui::DragFloat2("##kp", v, 0.002f, -1, 2, "%.3f")) { key.x = v[0]; key.y = v[1]; ch = true; } }
                    Prop("Size"); ch |= ImGui::SliderFloat("##ks", &key.scale, 0.05f, 5, "x %.2f");
                    Prop("Shows"); ch |= ImGui::SliderFloat("##ka", &key.alpha, 0, 1, "%.2f");
                    Prop("Smooth"); ch |= ImGui::Checkbox("##ksm", &key.smooth);
                    if (ImGui::IsItemHovered()) ImGui::SetTooltip("On: it eases into this keyframe (slows down to arrive). Off: a steady move.");
                    ImGui::TreePop();
                }
                ImGui::PopID();
            }
            if (drop >= 0) { it.keys.erase(it.keys.begin() + drop); tlKeySel = -1; ch = true; }
            Hint(it.keys.empty() ? "Make a picture glide across, zoom in slowly, or fade half away: put a keyframe at one time, move the playhead, put another, and drag it on the canvas to where it should be then. In between it moves on its own."
                                 : "Dragging it on the canvas changes (or makes) the keyframe at the playhead. Diamonds on its timeline bar: drag to move one, right-click to delete it.");
        }
    }
    void ScreenSoundTab(mc::Screen& sc, bool& ch) {
        ImGui::BeginChild("sndtab", ImVec2(0, 0));
        ImGui::SeparatorText("Music");
        { const char* mm[] = { "Keep what is playing", "Play this (it loops)", "Silence" }; Prop("When it shows"); ch |= ImGui::Combo("##mmode", &sc.musicMode, mm, 3); }
        if (sc.musicMode == 1) { Prop("Music"); ch |= SoundEdit("##music", sc.music, false); }
        if (sc.musicMode != 0) { Prop("Fades over"); ch |= ImGui::SliderFloat("##mfade", &sc.musicFade, 0, 6, "%.1f s"); }
        Hint("WAV, MP3, M4A, WMA or FLAC from the game's sounds (import them in the sound pickers). \"Keep\" lets the music of the screen before go on (the Options screen keeps the main menu's). Playing a game fades it out.");
        if (sc.role == ScreenRole::ItemGet) {
            ImGui::SeparatorText("Item pop-up");
            Prop("A button closes it after"); ch |= ImGui::SliderFloat("##hold", &sc.holdMin, 0, 5, "%.1f s");
            Hint("Jump, fire, Enter or a click closes it, but not before this (so a jump you were holding doesn't skip it). The fanfare and the music: Player > Items > Item pop-up. What it says: each item's Pop-up button there.");
        }
        ImGui::SeparatorText("Goes on by itself (splash screens, intros)");
        if (sc.useStack) { Prop("After"); ImGui::Text("%.1f s (as long as its stack)", sc.duration); }
        else { Prop("After"); ch |= ImGui::SliderFloat("##sqdur", &sc.duration, 0, 120, sc.duration <= 0 ? "never (stays)" : "%.1f s"); }
        Prop("Or when the video ends"); ch |= ImGui::Checkbox("##sqvid", &sc.untilVideoEnds);
        Prop("Then"); if (ImGui::BeginCombo("##sqnext", sc.next.empty() ? "(the main menu)" : sc.next.c_str())) {
            if (ImGui::Selectable("(the main menu)", sc.next.empty())) { sc.next.clear(); ch = true; }
            for (const mc::Screen& o : screens.screens) if (&o != &sc && ImGui::Selectable(o.name.c_str(), o.name == sc.next)) { sc.next = o.name; ch = true; }
            ImGui::EndCombo();
        }
        Prop("A key or click skips"); ch |= ImGui::Checkbox("##sqskip", &sc.skippable);
        Hint("The role \"Splash (shown first)\": playing from the menu (F6) starts there and goes screen to screen to the main menu. The role \"Intro of a new game\": shown after picking an empty file, screen to screen, then the game starts. A video background with \"or when the video ends\" makes an intro movie.");
        ImGui::SeparatorText("This screen's interface sounds");
        Prop("Picking"); ch |= SoundEdit("##shov", sc.sounds.hover, false);
        Prop("Using"); ch |= SoundEdit("##sclk", sc.sounds.click, false);
        Prop("Going back"); ch |= SoundEdit("##sbak", sc.sounds.back, false);
        ImGui::TextDisabled("(empty: the game's, below)");
        ImGui::SeparatorText("Starting a file (picking it on the Files screen, Continue)");
        Prop("Game-start sound"); ch |= SoundEdit("##gstart", screens.startSound, true);
        Prop("Fade as long as the sound"); ch |= ImGui::Checkbox("##gsfw", &screens.fadeWithSound);
        if (!screens.fadeWithSound || screens.startSound.empty()) { Prop("Fade to black"); ch |= ImGui::SliderFloat("##gsfd", &screens.startFade, 0.1f, 8, "%.1f s"); }
        Hint("The sound plays, the screen (and the music) fade to black, then the game fades in. An empty file goes to the screen with the role \"Intro of a new game\" first (the story), then into the game.");
        ImGui::SeparatorText("The game's interface sounds (every screen and the pause menu)");
        Prop("Picking"); ch |= SoundEdit("##ghov", screens.sounds.hover, false);
        Prop("Using"); ch |= SoundEdit("##gclk", screens.sounds.click, false);
        Prop("Going back"); ch |= SoundEdit("##gbak", screens.sounds.back, false);
        Hint("Picking: the mouse or W / S moves to another button or row. Using: a click / Enter (and changing an option). Going back: Back, Esc.");
        ImGui::EndChild();
    }
    void ScreenBgTab(mc::Screen& sc, bool& ch) {
        float ui = settings.uiScale, propW = 380 * ui, sp = ImGui::GetStyle().ItemSpacing.x;
        float aw = std::max(200.f, ImGui::GetContentRegionAvail().x - propW - sp), ah = ImGui::GetContentRegionAvail().y;
        ImGui::BeginChild("bgprev", ImVec2(aw, ah), ImGuiChildFlags_None, ImGuiWindowFlags_NoScrollbar);
        { float aspect = (float)std::max(1, cw) / std::max(1, ch_()); float w = aw, h = w / aspect; if (h > ah * 0.85f) { h = ah * 0.85f; w = h * aspect; } ScreenPreviewImage(w, h); }
        if (sc.bg.kind == BgKind::World || sc.bg.kind == BgKind::Game) Hint("Here the preview shows the editor's own view in its place; playing, it is the world through the camera (or the game itself).");
        ImGui::EndChild();
        ImGui::SameLine();
        ImGui::BeginChild("bgprops", ImVec2(propW, ah), ImGuiChildFlags_Borders);
        ScreenBg& b = sc.bg;
        Prop("Background"); if (ImGui::BeginCombo("##bgk", bgKindName(b.kind))) { for (int k = 0; k < (int)BgKind::COUNT; k++) if (ImGui::Selectable(bgKindName((BgKind)k), (int)b.kind == k)) { b.kind = (BgKind)k; ch = true; } ImGui::EndCombo(); }
        switch (b.kind) {
        case BgKind::Color: Prop("Top"); ch |= ColorU32("##bgc1", b.color); Prop("Bottom"); ch |= ColorU32("##bgc2", b.color2); break;
        case BgKind::Image: case BgKind::Video: {
            bool vid = b.kind == BgKind::Video;
            Prop(vid ? "Video" : "Picture / GIF"); ch |= FileCombo("##bgf", b.file, vid);
            const char* fits[] = { "Fill (cut what sticks out)", "All of it (bars)", "Stretch" }; Prop("Fit"); ch |= ImGui::Combo("##bgfit", &b.fit, fits, 3);
            Prop("Speed"); ch |= ImGui::SliderFloat("##bgsp", &b.speed, 0.1f, 3, "%.2fx"); Prop("Loops"); ch |= ImGui::Checkbox("##bglp", &b.loop);
            Hint(vid ? "MP4, WMV, AVI, MOV... anything Windows itself can play. Kept in the game's \"screens\" folder." : "PNG, JPG, BMP or an animated GIF. Kept in the game's \"screens\" folder.");
            break; }
        case BgKind::World: {
            Prop("World"); if (ImGui::BeginCombo("##bgw", b.world.empty() ? "(this one)" : b.world.c_str())) { for (const std::string& w : worldList) if (ImGui::Selectable(w.c_str(), w == b.world)) { b.world = w; ch = true; } ImGui::EndCombo(); }
            Prop("Camera object");
            if (b.world.empty() || b.world == CurrentWorld()) {
                if (ImGui::BeginCombo("##bgcam", b.camera.empty() ? "(the spawn point)" : b.camera.c_str())) {
                    if (ImGui::Selectable("(the spawn point)", b.camera.empty())) { b.camera.clear(); ch = true; }
                    for (const WorldObject& o : objects) if (ImGui::Selectable(o.name.c_str(), o.name == b.camera)) { b.camera = o.name; ch = true; }
                    ImGui::EndCombo();
                }
            } else ch |= ImGui::InputText("##bgcam", &b.camera);
            Hint("Place any object (a Map camera works nicely) where the view should be, turned the way it should look, and pick it here.");
            Prop("Looks up / down"); ch |= ImGui::SliderFloat("##bgtl", &b.tilt, -80, 80, "%.0f deg");
            Prop("Eye above it"); ch |= ImGui::SliderFloat("##bght", &b.height, -2, 6, "%.1f blocks");
            Prop("Turns slowly"); ch |= ImGui::SliderFloat("##bgtn", &b.turn, -20, 20, b.turn == 0 ? "no" : "%.1f deg/s");
            break; }
        case BgKind::Game: Hint("The game as it is when the screen opens (paused): good for the death screen, with a blur or grey in the compositor."); break;
        default: break;
        }
        Prop("Darker"); ch |= ImGui::SliderFloat("##bgdim", &b.dim, 0, 1, "%.2f");
        ImGui::EndChild();
    }

    // ---- the compositor's node editor (like Blender's): drag nodes, drag from an output to an input, right click to add
    void NodeEditor(mc::Screen& sc, bool& ch) {
        Compositor& g = sc.comp; float ui = settings.uiScale, z = nodeZoom * ui;
        ImGuiIO& io = ImGui::GetIO();
        float propW = 300 * ui, sp = ImGui::GetStyle().ItemSpacing.x;
        float aw = std::max(200.f, ImGui::GetContentRegionAvail().x - propW - sp), ah = ImGui::GetContentRegionAvail().y;
        ImGui::BeginChild("nodes", ImVec2(aw, ah), ImGuiChildFlags_Borders, ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoScrollWithMouse);
        ImDrawList* dl = ImGui::GetWindowDrawList(); ImVec2 o = ImGui::GetCursorScreenPos(), csz = ImGui::GetContentRegionAvail();
        ImVec2 origin(o.x + nodePan.x, o.y + nodePan.y);
        // the background grid
        dl->AddRectFilled(o, ImVec2(o.x + csz.x, o.y + csz.y), IM_COL32(28, 30, 34, 255));
        float gs = 32 * z;
        for (float x = std::fmod(nodePan.x, gs); x < csz.x; x += gs) dl->AddLine(ImVec2(o.x + x, o.y), ImVec2(o.x + x, o.y + csz.y), IM_COL32(255, 255, 255, 12));
        for (float y = std::fmod(nodePan.y, gs); y < csz.y; y += gs) dl->AddLine(ImVec2(o.x, o.y + y), ImVec2(o.x + csz.x, o.y + y), IM_COL32(255, 255, 255, 12));
        // the canvas itself: pan with the middle / right mouse, zoom with the wheel, right click: add
        ImGui::SetCursorScreenPos(o); ImGui::SetNextItemAllowOverlap();   // (the nodes on it still get the mouse)
        ImGui::InvisibleButton("##ncanvas", csz, ImGuiButtonFlags_MouseButtonLeft | ImGuiButtonFlags_MouseButtonRight | ImGuiButtonFlags_MouseButtonMiddle);
        bool canvasHov = ImGui::IsItemHovered();
        if (ImGui::IsItemActive() && (ImGui::IsMouseDragging(ImGuiMouseButton_Middle) || ImGui::IsMouseDragging(ImGuiMouseButton_Right))) { nodePan.x += io.MouseDelta.x; nodePan.y += io.MouseDelta.y; }
        if (canvasHov && io.MouseWheel != 0) {
            float nz = std::clamp(nodeZoom * (io.MouseWheel > 0 ? 1.1f : 0.9f), 0.4f, 1.8f), k = nz / nodeZoom;
            nodePan.x = io.MousePos.x - o.x - (io.MousePos.x - o.x - nodePan.x) * k; nodePan.y = io.MousePos.y - o.y - (io.MousePos.y - o.y - nodePan.y) * k; nodeZoom = nz;
        }
        if (canvasHov && ImGui::IsMouseClicked(0)) scrNode = 0;
        static ImVec2 addAt; if (canvasHov && ImGui::IsMouseReleased(ImGuiMouseButton_Right) && io.MouseDragMaxDistanceSqr[ImGuiMouseButton_Right] < 25) {   // a right click (not a drag)
            addAt = ImVec2((io.MousePos.x - origin.x) / z, (io.MousePos.y - origin.y) / z); ImGui::OpenPopup("addnode"); }
        // where each socket is (filled while drawing the nodes)
        std::map<int, ImVec2> outPos; std::map<std::pair<int, int>, ImVec2> inPos;
        float nodeW = 190 * z, head = 24 * z, row = 22 * z;
        auto colOf = [](const char* grp) -> ImU32 { std::string g = grp; return g == "Input" ? IM_COL32(150, 60, 60, 255) : g == "Output" ? IM_COL32(70, 70, 80, 255) : g == "Color" ? IM_COL32(150, 130, 50, 255)
                                                   : g == "Filter" ? IM_COL32(90, 70, 150, 255) : g == "Distort" ? IM_COL32(50, 110, 140, 255) : IM_COL32(60, 120, 80, 255); };
        dl->ChannelsSplit(2);
        int dragNode = 0; static int movingNode = 0;
        for (CompNode& n : g.nodes) {
            const NodeInfo& in = nodeInfo(n.type); ImGui::PushID(n.id);
            ImVec2 p(origin.x + n.x * z, origin.y + n.y * z);
            int rows = in.inputs + in.params + in.colors + (in.modes ? 1 : 0) + (n.type != NodeType::Output ? 1 : 0);
            float hgt = head + rows * row + 8 * z;
            ImVec2 q(p.x + nodeW, p.y + hgt);
            dl->ChannelsSetCurrent(1);
            // the title: drag to move, click to pick
            ImGui::SetCursorScreenPos(p); ImGui::InvisibleButton("##title", ImVec2(nodeW, head));
            if (ImGui::IsItemActivated()) { scrNode = n.id; movingNode = n.id; }
            if (ImGui::IsItemActive() && movingNode == n.id && ImGui::IsMouseDragging(0)) { n.x += io.MouseDelta.x / z; n.y += io.MouseDelta.y / z; dragNode = n.id; }
            if (ImGui::IsItemDeactivated() && movingNode == n.id) { movingNode = 0; ch = true; }
            if (ImGui::IsItemHovered() && in.tip && *in.tip) ImGui::SetTooltip("%s", in.tip);
            dl->AddText(ImGui::GetFont(), ImGui::GetFontSize() * nodeZoom, ImVec2(p.x + 8 * z, p.y + 4 * z), IM_COL32(255, 255, 255, 255), (std::string(in.name) + (n.mute ? "  (muted)" : "")).c_str());
            float y = p.y + head + 4 * z;
            if (n.type != NodeType::Output) {   // its output (right side)
                ImVec2 s(q.x, y + row * 0.5f); outPos[n.id] = s;
                dl->AddText(ImGui::GetFont(), ImGui::GetFontSize() * nodeZoom * 0.9f, ImVec2(q.x - 60 * z, y + 2 * z), IM_COL32(220, 220, 220, 255), "Image");
                ImGui::SetCursorScreenPos(ImVec2(s.x - 8 * z, s.y - 8 * z)); ImGui::InvisibleButton("##out", ImVec2(16 * z, 16 * z));
                if (ImGui::IsItemActivated()) { linkFrom = n.id; linkDragging = true; linkTo = 0; }
                y += row;
            }
            for (int k = 0; k < in.inputs; k++) {   // inputs (left side)
                ImVec2 s(p.x, y + row * 0.5f); inPos[{ n.id, k }] = s;
                dl->AddText(ImGui::GetFont(), ImGui::GetFontSize() * nodeZoom * 0.9f, ImVec2(p.x + 12 * z, y + 2 * z), IM_COL32(220, 220, 220, 255), in.inName[k]);
                ImGui::SetCursorScreenPos(ImVec2(s.x - 8 * z, s.y - 8 * z)); ImGui::PushID(100 + k); ImGui::InvisibleButton("##in", ImVec2(16 * z, 16 * z));
                if (ImGui::IsItemActivated() && n.in[k]) { linkFrom = n.in[k]; n.in[k] = 0; linkDragging = true; ch = true; }   // pick a wire up again
                if (ImGui::IsItemHovered() && ImGui::IsMouseClicked(ImGuiMouseButton_Right)) { n.in[k] = 0; ch = true; }
                if (linkDragging && ImGui::IsMouseHoveringRect(ImVec2(s.x - 10 * z, s.y - 10 * z), ImVec2(s.x + 10 * z, s.y + 10 * z))) { linkTo = n.id; linkSlot = k; }
                ImGui::PopID();
                y += row;
            }
            ImGui::PushItemWidth(nodeW - 16 * z);
            for (int k = 0; k < in.params; k++) {   // its values
                ImGui::SetCursorScreenPos(ImVec2(p.x + 8 * z, y)); ImGui::PushID(200 + k);
                if (ImGui::SliderFloat("##p", &n.p[k], in.pMin[k], in.pMax[k], (std::string(in.pName[k]) + " %.2f").c_str())) ch = true;
                ImGui::PopID(); y += row;
            }
            for (int k = 0; k < in.colors; k++) {
                ImGui::SetCursorScreenPos(ImVec2(p.x + 8 * z, y)); ImGui::PushID(300 + k);
                if (ColorU32("##c", n.c[k])) ch = true;
                ImGui::PopID(); y += row;
            }
            if (in.modes) { ImGui::SetCursorScreenPos(ImVec2(p.x + 8 * z, y)); if (ImGui::Combo("##mode", &n.mode, in.modeName, in.modes)) ch = true; y += row; }
            ImGui::PopItemWidth();
            // the box behind it all
            dl->ChannelsSetCurrent(0);
            bool picked = scrNode == n.id;
            dl->AddRectFilled(p, q, IM_COL32(48, 50, 56, 240), 6 * z);
            dl->AddRectFilled(p, ImVec2(q.x, p.y + head), colOf(in.group), 6 * z, ImDrawFlags_RoundCornersTop);
            dl->AddRect(p, q, picked ? IM_COL32(255, 200, 60, 255) : IM_COL32(0, 0, 0, 160), 6 * z, ImDrawFlags_None, picked ? 2.f : 1.f);
            for (int k = 0; k < in.inputs; k++) { ImVec2 s = inPos[{ n.id, k }]; dl->AddCircleFilled(s, 5 * z, n.in[k] ? IM_COL32(230, 200, 80, 255) : IM_COL32(140, 140, 150, 255)); }
            if (n.type != NodeType::Output) dl->AddCircleFilled(outPos[n.id], 5 * z, IM_COL32(230, 200, 80, 255));
            ImGui::PopID();
        }
        dl->ChannelsMerge();
        // the wires
        auto wire = [&](ImVec2 a, ImVec2 b, ImU32 c) { float d = std::max(40.f * z, std::fabs(b.x - a.x) * 0.5f); dl->AddBezierCubic(a, ImVec2(a.x + d, a.y), ImVec2(b.x - d, b.y), b, c, 2.5f * z); };
        for (const CompNode& n : g.nodes) for (int k = 0; k < nodeInfo(n.type).inputs; k++) if (n.in[k] && outPos.count(n.in[k])) wire(outPos[n.in[k]], inPos[{ n.id, k }], IM_COL32(200, 200, 210, 220));
        if (linkDragging) {
            if (outPos.count(linkFrom)) wire(outPos[linkFrom], io.MousePos, IM_COL32(255, 220, 120, 255));
            if (!ImGui::IsMouseDown(0)) {   // let go: over an input, it connects
                if (linkTo && linkSlot >= 0) { if (g.connect(linkFrom, linkTo, linkSlot)) ch = true; else Toast("That wire would make a loop"); }
                linkDragging = false; linkFrom = linkTo = 0; linkSlot = -1;
            } else { linkTo = 0; linkSlot = -1; }   // (found again next frame while hovering)
        }
        if (ImGui::BeginPopup("addnode")) {   // add a node where you clicked
            const char* groupsN[] = { "Input", "Color", "Filter", "Distort", "Stylize", "Output" };
            for (const char* grp : groupsN) {
                if (!ImGui::BeginMenu(grp)) continue;
                for (int t = 0; t < (int)NodeType::COUNT; t++) { const NodeInfo& in = nodeInfo((NodeType)t); if (std::string(in.group) != grp) continue;
                    if (ImGui::MenuItem(in.name)) { if ((NodeType)t == NodeType::Output && g.output()) Toast("There is an Output already"); else { scrNode = g.add((NodeType)t, addAt.x, addAt.y); ch = true; } } }
                ImGui::EndMenu();
            }
            ImGui::EndPopup();
        }
        if (scrNode && ImGui::IsWindowFocused() && (ImGui::IsKeyPressed(ImGuiKey_Delete) || ImGui::IsKeyPressed(ImGuiKey_X)) && !io.WantTextInput) { g.remove(scrNode); scrNode = 0; ch = true; }
        if (scrNode && ImGui::IsWindowFocused() && ImGui::IsKeyPressed(ImGuiKey_M) && !io.WantTextInput) if (CompNode* n = g.find(scrNode)) { n->mute = !n->mute; ch = true; }
        ImGui::SetCursorScreenPos(ImVec2(o.x + 8, o.y + csz.y - ImGui::GetTextLineHeight() - 6));
        ImGui::TextDisabled("Right click: add a node.  Drag from a node's Image out to an input.  Right / middle drag: move around, wheel: zoom.  Delete / X: remove, M: mute.");
        ImGui::EndChild();
        ImGui::SameLine();
        ImGui::BeginChild("nodeprev", ImVec2(propW, ah), ImGuiChildFlags_Borders);
        ImGui::TextDisabled("WHAT IT LOOKS LIKE");
        { float w = ImGui::GetContentRegionAvail().x, h = w * std::max(1, ch_()) / std::max(1, cw); ScreenPreviewImage(w, h); }
        if (CompNode* n = g.find(scrNode)) {
            ImGui::SeparatorText(nodeInfo(n->type).name);
            if (nodeInfo(n->type).tip && *nodeInfo(n->type).tip) ImGui::TextWrapped("%s", nodeInfo(n->type).tip);
            if (n->type != NodeType::Output && n->type != NodeType::Background && n->type != NodeType::UI) { if (ImGui::Checkbox("Muted (passes its picture through)", &n->mute)) ch = true; }
            if (ImGui::Button("Remove this node")) { g.remove(scrNode); scrNode = 0; ch = true; }
        }
        ImGui::Spacing();
        if (ImGui::Button("Start over with the usual graph")) { sc.comp = defaultCompositor(); scrNode = 0; ch = true; }
        if (!g.output()) Hint("No Output node: the screen shows its background with the items over it.");
        ImGui::EndChild();
    }

    // ---- Player editor > Menu: pages (tabs), their panes, the panes' items
    bool menuEdAlways = false; int menuEdPane = 0, menuEdItem = -1; bool selectMenuTab = false, selectVisorsTab = false; int visorEd = 1;
    float menuDragX = 0, menuDragY = 0; int menuDragMode = 0;   // 1 move, 2 resize
    std::vector<MenuPane>* MenuEdPanes() {
        if (menuEdAlways) return &menu.always;
        if (menuEdPage < 0 || menuEdPage >= (int)menu.pages.size()) return nullptr;
        return &menu.pages[menuEdPage].panes;
    }
    MenuPane* MenuEdPane() { auto* v = MenuEdPanes(); return v && menuEdPane >= 0 && menuEdPane < (int)v->size() ? &(*v)[menuEdPane] : nullptr; }
    MenuItem* MenuEdItem() { MenuPane* p = MenuEdPane(); return p && menuEdItem >= 0 && menuEdItem < (int)p->items.size() ? &p->items[menuEdItem] : nullptr; }
    static bool ColorU32(const char* id, uint32_t& v) {
        float c[3] = { ((v >> 16) & 255) / 255.f, ((v >> 8) & 255) / 255.f, (v & 255) / 255.f };
        if (!ImGui::ColorEdit3(id, c)) return false;
        v = ((uint32_t)(c[0] * 255 + 0.5f) << 16) | ((uint32_t)(c[1] * 255 + 0.5f) << 8) | (uint32_t)(c[2] * 255 + 0.5f); return true;
    }
    void MenuList(bool& ch) {
        auto paneNodes = [&](std::vector<MenuPane>& panes, bool always, int page) {
            for (int pi = 0; pi < (int)panes.size(); pi++) {
                MenuPane& p = panes[pi]; ImGui::PushID(pi);
                bool selP = menuEdAlways == always && (always || menuEdPage == page) && menuEdPane == pi && menuEdItem < 0;
                ImGuiTreeNodeFlags f = ImGuiTreeNodeFlags_OpenOnArrow | ImGuiTreeNodeFlags_DefaultOpen | ImGuiTreeNodeFlags_SpanAvailWidth | (selP ? ImGuiTreeNodeFlags_Selected : 0) | (p.items.empty() ? ImGuiTreeNodeFlags_Leaf : 0);
                bool open = ImGui::TreeNodeEx("pane", f, "%s", (p.name + "  (pane)").c_str());
                if (ImGui::IsItemClicked() && !ImGui::IsItemToggledOpen()) { menuEdAlways = always; if (!always) menuEdPage = page; menuEdPane = pi; menuEdItem = -1; }
                if (open) {
                    for (int ii = 0; ii < (int)p.items.size(); ii++) {
                        ImGui::PushID(ii); bool selI = menuEdAlways == always && (always || menuEdPage == page) && menuEdPane == pi && menuEdItem == ii;
                        std::string l = p.items[ii].name + "  - " + menuKindName(p.items[ii].kind);
                        ImGui::TreeNodeEx("it", ImGuiTreeNodeFlags_Leaf | ImGuiTreeNodeFlags_NoTreePushOnOpen | ImGuiTreeNodeFlags_SpanAvailWidth | (selI ? ImGuiTreeNodeFlags_Selected : 0), "%s", l.c_str());
                        if (ImGui::IsItemClicked()) { menuEdAlways = always; if (!always) menuEdPage = page; menuEdPane = pi; menuEdItem = ii; }
                        ImGui::PopID();
                    }
                    ImGui::TreePop();
                }
                ImGui::PopID();
            }
        };
        ImGui::SeparatorText("On every page");
        ImGui::PushID("always"); paneNodes(menu.always, true, -1); ImGui::PopID();
        ImGui::SeparatorText("Pages");
        for (int pg = 0; pg < (int)menu.pages.size(); pg++) {
            ImGui::PushID(1000 + pg); MenuPage& P = menu.pages[pg];
            bool selPg = !menuEdAlways && menuEdPage == pg && menuEdPane < 0;
            std::string l = P.name + (pg == 0 ? "  (opens first)" : "") + (P.tab ? "" : "  (not a tab)");
            bool open = ImGui::TreeNodeEx("page", ImGuiTreeNodeFlags_OpenOnArrow | ImGuiTreeNodeFlags_DefaultOpen | ImGuiTreeNodeFlags_SpanAvailWidth | (selPg ? ImGuiTreeNodeFlags_Selected : 0), "%s", l.c_str());
            if (ImGui::IsItemClicked() && !ImGui::IsItemToggledOpen()) { menuEdAlways = false; menuEdPage = pg; menuEdPane = -1; menuEdItem = -1; }
            if (open) { paneNodes(P.panes, false, pg); ImGui::TreePop(); }
            ImGui::PopID();
        }
        ImGui::Separator();
        if (ImGui::Button("+ Page")) { MenuPage p; p.name = "Page " + std::to_string(menu.pages.size() + 1); MenuPane pn; pn.name = "Pane"; p.panes.push_back(pn); menu.pages.push_back(p); menuEdAlways = false; menuEdPage = (int)menu.pages.size() - 1; menuEdPane = -1; menuEdItem = -1; ch = true; }
        if (menu.optionsPage() < 0) { ImGui::SameLine(); if (ImGui::Button("+ Options page")) { menu.pages.push_back(defaultOptionsPage()); menuEdAlways = false; menuEdPage = (int)menu.pages.size() - 1; menuEdPane = 0; menuEdItem = -1; ch = true; }
            if (ImGui::IsItemHovered()) ImGui::SetTooltip("The player's options (Sound, Graphics, Controls) as a page of the menu.\nOptions buttons lead there."); }
        ImGui::SameLine(); if (ImGui::Button("+ Pane")) { if (auto* v = MenuEdPanes()) { MenuPane pn; pn.name = "Pane " + std::to_string(v->size() + 1); v->push_back(pn); menuEdPane = (int)v->size() - 1; menuEdItem = -1; ch = true; } }
        ImGui::SameLine(); if (ImGui::Button("+ Item...")) ImGui::OpenPopup("additem");
        if (ImGui::BeginPopup("additem")) {
            for (int k = 0; k < (int)MenuKind::COUNT; k++) if (ImGui::Selectable(menuKindName((MenuKind)k))) {
                MenuPane* p = MenuEdPane(); if (!p) { Toast("Pick a pane first"); break; }
                MenuItem it; it.kind = (MenuKind)k; it.name = menuKindName((MenuKind)k);
                if (it.kind == MenuKind::Button) { it.text = "Button"; it.act = MenuAct::Resume; }
                if (it.kind == MenuKind::Text) it.text = "Text";
                if (it.kind == MenuKind::Panel) { it.w = 0.5f; it.h = 0.3f; }
                if (it.kind == MenuKind::ItemList || it.kind == MenuKind::BeamList || it.kind == MenuKind::ScanList || it.kind == MenuKind::ScanText || it.kind == MenuKind::ScanModel) { it.y = 0.15f; it.h = 0.8f; it.textSize = 32; }
                p->items.push_back(it); menuEdItem = (int)p->items.size() - 1; ch = true;
            }
            ImGui::EndPopup();
        }
        if (ImGui::Button("Duplicate")) {
            if (MenuItem* it = MenuEdItem()) { MenuItem c = *it; c.name += " copy"; c.y = std::min(0.95f, c.y + 0.05f); MenuEdPane()->items.push_back(c); menuEdItem = (int)MenuEdPane()->items.size() - 1; ch = true; }
            else if (MenuPane* p = MenuEdPane()) { MenuPane c = *p; c.name += " copy"; c.pos.y -= 0.1; MenuEdPanes()->push_back(c); menuEdPane = (int)MenuEdPanes()->size() - 1; ch = true; }
            else if (!menuEdAlways && menuEdPage >= 0 && menuEdPage < (int)menu.pages.size()) { MenuPage c = menu.pages[menuEdPage]; c.name += " copy"; menu.pages.push_back(c); menuEdPage = (int)menu.pages.size() - 1; ch = true; }
        }
        ImGui::SameLine(); if (ImGui::Button("Delete")) {
            if (MenuEdItem()) { MenuEdPane()->items.erase(MenuEdPane()->items.begin() + menuEdItem); menuEdItem = -1; ch = true; }
            else if (MenuEdPane()) { MenuEdPanes()->erase(MenuEdPanes()->begin() + menuEdPane); menuEdPane = -1; ch = true; }
            else if (!menuEdAlways && menuEdPage >= 0 && menuEdPage < (int)menu.pages.size() && menu.pages.size() > 1) { menu.pages.erase(menu.pages.begin() + menuEdPage); menuEdPage = 0; ch = true; }
        }
        auto move = [&](int d) {
            if (MenuEdItem()) { auto& v = MenuEdPane()->items; int j = menuEdItem + d; if (j >= 0 && j < (int)v.size()) { std::swap(v[menuEdItem], v[j]); menuEdItem = j; ch = true; } }
            else if (MenuEdPane()) { auto& v = *MenuEdPanes(); int j = menuEdPane + d; if (j >= 0 && j < (int)v.size()) { std::swap(v[menuEdPane], v[j]); menuEdPane = j; ch = true; } }
            else if (!menuEdAlways) { int j = menuEdPage + d; if (j >= 0 && j < (int)menu.pages.size()) { std::swap(menu.pages[menuEdPage], menu.pages[j]); menuEdPage = j; ch = true; } }
        };
        ImGui::SameLine(); if (ImGui::ArrowButton("##mup", ImGuiDir_Up)) move(-1);
        ImGui::SameLine(); if (ImGui::ArrowButton("##mdn", ImGuiDir_Down)) move(1);
        ImGui::Spacing();
        if (ImGui::SmallButton("Use the new three-pane menu")) ImGui::OpenPopup("menureset");
        if (ImGui::IsItemHovered()) ImGui::SetTooltip("The sharp helmet menu: tabs on top (System, Inventory, Log), three bent panes, Options / Quick save / Quit below.");
        ImGui::SameLine(); if (ImGui::SmallButton("The first menu")) ImGui::OpenPopup("menuclassic");
        if (ImGui::BeginPopup("menuclassic")) { ImGui::TextUnformatted("Replace this whole menu with the first one (Main, Inventory, Logbook)?"); if (ImGui::Button("Yes, replace it")) { menu = classicMenu(); menuEdAlways = false; menuEdPage = 0; menuEdPane = -1; menuEdItem = -1; ch = true; ImGui::CloseCurrentPopup(); } ImGui::EndPopup(); }
        if (ImGui::BeginPopup("menureset")) { ImGui::TextUnformatted("Replace this whole menu with the new three-pane one?"); if (ImGui::Button("Yes, replace it")) { menu = defaultMenu(); menuEdAlways = false; menuEdPage = 0; menuEdPane = -1; menuEdItem = -1; ch = true; ImGui::CloseCurrentPopup(); } ImGui::EndPopup(); }
    }
    void MenuCanvas(ImVec2 avail, bool& ch) {   // the picked pane laid out flat: click an item to pick it, drag to move, the corner to resize
        MenuPane* p = MenuEdPane();
        if (!p) { ImGui::TextDisabled("Pick a pane (or an item) on the left to lay it out here."); return; }
        int idx = (menuEdAlways ? 0 : (int)menu.always.size()) + menuEdPane;
        float W = (float)MENU_PANE_W, H = (float)menuPaneHeight(*p), k = std::min(avail.x / W, avail.y / H); ImVec2 sz(W * k, H * k);
        ImVec2 o = ImGui::GetCursorScreenPos(); ImDrawList* dl = ImGui::GetWindowDrawList();
        dl->AddRectFilled(o, ImVec2(o.x + sz.x, o.y + sz.y), IM_COL32(20, 24, 30, 255));
        if (idx < (int)menuTargets.size() && menuTargets[idx].srv) dl->AddImage((ImTextureID)(intptr_t)menuTargets[idx].srv.Get(), o, ImVec2(o.x + sz.x, o.y + sz.y));
        ImGui::InvisibleButton("menucanvas", sz);
        ImGuiIO& io = ImGui::GetIO(); float mx = (io.MousePos.x - o.x) / sz.x, my = (io.MousePos.y - o.y) / sz.y;
        for (int i = 0; i < (int)p->items.size(); i++) {
            const MenuItem& it = p->items[i]; ImVec2 a(o.x + it.x * sz.x, o.y + it.y * sz.y), b(o.x + (it.x + it.w) * sz.x, o.y + (it.y + it.h) * sz.y);
            bool sel = i == menuEdItem; dl->AddRect(a, b, sel ? IM_COL32(255, 210, 80, 255) : IM_COL32(255, 255, 255, 60), 0, ImDrawFlags_None, sel ? 2.f : 1.f);
            if (sel) dl->AddRectFilled(ImVec2(b.x - 8, b.y - 8), b, IM_COL32(255, 210, 80, 255));
        }
        if (ImGui::IsItemActivated()) {
            menuDragMode = 0; MenuItem* s = MenuEdItem();
            if (s && std::fabs(mx - (s->x + s->w)) * sz.x < 10 && std::fabs(my - (s->y + s->h)) * sz.y < 10) menuDragMode = 2;
            else {
                int hitI = -1; for (int i = (int)p->items.size() - 1; i >= 0; i--) { const MenuItem& it = p->items[i]; if (mx >= it.x && mx <= it.x + it.w && my >= it.y && my <= it.y + it.h) { hitI = i; break; } }
                menuEdItem = hitI; if (hitI >= 0) menuDragMode = 1;
            }
            menuDragX = mx; menuDragY = my;
        }
        if (ImGui::IsItemActive() && menuDragMode) if (MenuItem* s = MenuEdItem()) {
            float dx = mx - menuDragX, dy = my - menuDragY; menuDragX = mx; menuDragY = my;
            if (dx != 0 || dy != 0) {
                if (menuDragMode == 1) { s->x = std::clamp(s->x + dx, -0.5f, 1.f); s->y = std::clamp(s->y + dy, -0.5f, 1.f); }
                else { s->w = std::clamp(s->w + dx, 0.02f, 1.5f); s->h = std::clamp(s->h + dy, 0.02f, 1.5f); }
                ch = true;
            }
        }
        ImGui::TextDisabled("%s: drag an item to move it, its corner to resize it", p->name.c_str());
    }
