            { const char* lm[] = { "Hold the button (like Prime)", "A press locks, the next lets go" }; Prop("Button"); ch |= ImGui::Combo("##lkm", &L.mode, lm, 2); }
            Prop("Reach (blocks)"); ch |= ImGui::SliderFloat("##lkr", &L.range, 5, 150, "%.0f");
