            char path[256]; snprintf(path, sizeof path, "%s/%02d_project_manager.png", shotDir.c_str(), ++n);
            SaveShot(std::string(path)); swap->Present(0, 0); retired.clear(); Log(std::string(path));
            Projects::remove(a); Projects::remove(b);
